    inset-inline-end: calc(var(--switch-pad) + var(--switch-travel) - var(--switch-reach));
  }

  .root:active:not([data-disabled], [data-busy]) .thumb[data-checked] {
    inset-inline-start: calc(var(--switch-pad) + var(--switch-travel) - var(--switch-reach));
  }

