    opacity: 1;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter);
    animation: switch-working var(--ui-dur-pulse) var(--ui-ease-pulse) infinite alternate;
  }

  @keyframes switch-working {
    from {
      scale: 1;
    }
    to {
      scale: 0.6;
    }
  }

  .root[data-busy] {
    cursor: default;
  }

  .text {
    display: grid;
    gap: 2px;
    min-width: 0;
  }

  .label {
    font-weight: var(--ui-weight-medium);
  }

  .description {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .root[data-disabled] {
    cursor: default;
  }

  .root[data-disabled] :is(.control, .label) {
    opacity: 0.5;
  }

