    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .disclosure::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: var(--connections-head-radius);
  }

  .disclosure:focus {
    outline: none;
  }

  .disclosure:focus-visible::after {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .row[data-status="disabled"] .name {
    color: var(--ui-muted);
  }

  /* One quiet line: the tool count, or what's wrong and the one thing to do. */
  .meta {
    display: flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .meta[data-status="needs-auth"] {
    color: var(--ui-warning-text);
  }

  .meta[data-status="error"] {
    color: var(--ui-danger-text);
  }

  .meta[data-status="disabled"] {
    color: var(--ui-subtle);
  }

  .sep {
    color: var(--ui-subtle);
  }

  /* A text button above the row's own button, like the switch. */
  .action {
    position: relative;
    z-index: 1;
    padding: 0;
    border: 0;
    background: none;
    color: var(--ui-foreground);
    font: inherit;
    font-weight: var(--ui-weight-medium);
    text-decoration: underline;
    text-decoration-color: var(--ui-border-strong);
    text-underline-offset: 3px;
    cursor: pointer;
    touch-action: manipulation;
    transition: text-decoration-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* 24px tall to the pointer, 40 to a finger, without moving the line. */
  .action::after {
    content: "";
    position: absolute;
    inset: -3px -4px;
  }

  @media (pointer: coarse) {
    .action::after {
      inset: -11px -6px;
    }
  }

  @media (hover: hover) {
    .action:hover {
      text-decoration-color: currentColor;
    }
  }

  .action:focus-visible {
    border-radius: 2px;
    outline: var(--ui-ring-focus);
    outline-offset: 2px;
  }

  .host {
    color: var(--ui-muted);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-code);
  }

  .control {
    position: relative;
    z-index: 1;
    display: flex;
  }

  /* The opened row: its address, what's wrong, its tools, then Disconnect. */
  .panel {
    display: grid;
    grid-template-rows: 0fr;
    margin-inline-start: var(--connections-indent);
    opacity: 0;
    transition:
      grid-template-rows var(--ui-dur-base) var(--ui-ease-collapse),
      opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .panel[data-open="true"] {
    grid-template-rows: 1fr;
    opacity: 1;
    transition:
      grid-template-rows var(--ui-dur-panel) var(--ui-ease-expand),
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2);
  }

  .clip {
    min-height: 0;
    overflow: hidden;
  }

  .panelInner {
    display: grid;
    gap: var(--ui-space-5);
    padding-top: var(--ui-space-4);
  }

  .about {
    display: grid;
    gap: var(--ui-space-1);
  }

  .problem {
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .problem[data-kind="error"] {
    color: var(--ui-danger-text);
  }

  .problem[data-kind="needs-auth"] {
    color: var(--ui-warning-text);
  }

  .section {
    display: grid;
    gap: var(--ui-space-2);
  }

  .sectionLabel {
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-sm);
  }

  .sectionNote {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .tools {
    display: grid;
    gap: var(--ui-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .granted {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    display: grid;
    gap: var(--ui-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .tool {
    display: grid;
    gap: 2px;
  }

  .toolName {
    justify-self: start;
    max-width: 100%;
    color: var(--ui-foreground);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-code);
    line-height: var(--ui-leading-md);
    overflow-wrap: anywhere;
  }

  .row[data-status="disabled"] .toolName {
    color: var(--ui-muted);
  }

  .toolDescription {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  /* The ghost button's label lines up with the tool names. */
  .more {
    margin: var(--ui-space-2) 0 0 -20px;
  }

  .granted li {
    display: grid;
    grid-template-columns: 16px minmax(0, 1fr);
    column-gap: var(--ui-space-2);
    align-items: start;
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
  }

  .bullet {
    width: 16px;
    height: 16px;
    margin-top: 3px;
    color: var(--ui-muted);
  }

  .account {
    color: var(--ui-foreground);
    overflow-wrap: anywhere;
  }

  .footer {
    display: flex;
  }

  .confirm {
    display: grid;
    gap: var(--ui-space-3);
    padding: var(--ui-space-3);
    border-radius: var(--ui-radius-md);
    background: var(--ui-fill);
  }

  .confirm[data-enter] {
    animation: connections-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes connections-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }

  .confirm p {
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .confirm strong {
    font-weight: var(--ui-weight-semibold);
  }

  .confirm .failure {
    color: var(--ui-danger-text);
  }

  .confirmActions {
    display: flex;
    justify-content: flex-end;
    gap: var(--ui-space-2);
  }

  .empty {
    display: grid;
    gap: var(--ui-space-1);
    justify-items: center;
    padding: var(--ui-space-6) var(--connections-pad);
    text-align: center;
  }

  .emptyTitle {
    margin: 0;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .emptyNote {
    max-width: 34ch;
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: balance;
  }

  /* Adding a server: a field, then the sign-in step. */
  .add {
    padding: var(--connections-pad);
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  .form {
    display: grid;
    gap: var(--ui-space-3);
  }

  .formActions {
    display: flex;
    justify-content: flex-end;
    gap: var(--ui-space-2);
  }

  /* Closed, adding is one row that reads like the servers above it. */
  .addRow {
    display: grid;
    grid-template-columns: var(--connections-mark) minmax(0, 1fr);
    column-gap: var(--ui-space-3);
    align-items: center;
    width: calc(100% + var(--ui-space-2) * 2);
    margin: calc(var(--ui-space-2) * -1);
    padding: var(--ui-space-2);
    border: 0;
    border-radius: var(--connections-head-radius);
    background: none;
    color: var(--ui-muted);
    font: var(--ui-weight-medium) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    text-align: start;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .addRow:hover {
      background: var(--ui-fill);
      color: var(--ui-foreground);
    }
  }

  .addRow:active {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  .addRow:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .addIcon {
    display: grid;
    place-items: center;
    width: var(--connections-mark);
    height: var(--connections-mark);
    border-radius: var(--ui-radius-sm);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
  }

  .addIcon > svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
  }

  .signin {
    display: grid;
    grid-template-columns: var(--connections-mark) minmax(0, 1fr);
    column-gap: var(--ui-space-3);
    align-items: start;
  }

  .signin[data-enter] {
    animation: connections-in var(--ui-dur-base) var(--ui-ease-enter);
  }

  .signinMark {
    display: grid;
    place-items: center;
    width: var(--connections-mark);
    height: var(--connections-mark);
    border-radius: var(--ui-radius-sm);
    background: var(--ui-fill);
    color: var(--ui-muted);
  }

  .signinText {
    display: grid;
    gap: var(--ui-space-1);
    min-width: 0;
  }

  .signinTitle {
    margin: 0;
    /* Level with the 32px mark. */
    padding-top: calc((var(--connections-mark) - var(--ui-leading-md)) / 2);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .signinTitle:focus {
    outline: none;
  }

  .signinNote,
  .waiting {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .waiting {
    color: var(--ui-foreground);
  }

  .signinActions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--ui-space-2);
    margin-top: var(--ui-space-3);
  }

  @media (max-width: 480px) {
    .panel {
      margin-inline-start: 0;
    }
    .signinActions > *,
    .confirmActions > * {
      flex: 1;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .row[data-arrived] {
      animation: connections-row-fade var(--ui-dur-fast) var(--ui-ease-enter);
    }
    .row[data-leaving] {
      transition: opacity var(--ui-dur-instant) var(--ui-ease-exit);
    }
    .panel,
    .panel[data-open="true"] {
      transition-property: opacity;
    }
    .confirm[data-enter],
    .signin[data-enter] {
      animation: none;
    }
  }
}

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type FormEvent, type KeyboardEvent, type ReactNode, type RefObject } from "react";
import { AnimatedSize } from "../animated-size/animated-size";
import { Button } from "../button/button";
import { ButtonLink } from "../button/button-link";
import { Icon } from "../icons/icons";
import { Switch } from "../switch/switch";
import { TextField } from "../text-field/text-field";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./connections.module.css";

export type ConnectionStatus = "connected" | "connecting" | "needs-auth" | "error" | "disabled";

export type ConnectionTool = {
  /** As the server names it: `create_booking`. */
  name: string;
  /** One line on what it does. */
  description?: string;
};

export type Connection = {
  id: string;
  name: string;
  /** Shown in mono: "mcp.acme.example.com". */
  host: string;
  /** A 20px logo. Without one, the first letter stands in. */
  mark?: ReactNode;
  status: ConnectionStatus;
  /** What the server offers. Leave out until it has answered. */
  tools?: ConnectionTool[];
  /** What the person allowed when they signed in: "Read your bookings". */
  granted?: string[];
  /** The account it's signed in as. */
  account?: string;
  /** With `error` or `needs-auth`: what happened. */
  message?: string;
};

export type AddServerState =
  | { status: "idle" }
  | { status: "checking"; url: string }
  | { status: "signing-in"; url: string; signInUrl: string; name?: string }
  | { status: "failed"; url: string; error: string };

type ConnectionsProps = {
  servers: Connection[];
  /** The agent's name, used in sentences: "Copper can’t use Ledger…". */
  agent: string;
  /** Controlled. Leave out `onAdd` to hide the add form. */
  add?: AddServerState;
  /** Called with a checked https URL. */
  onAdd?: (url: string) => void;
  onCancelAdd?: () => void;
  onToggle?: (id: string, on: boolean) => void;
  /** `needs-auth`: start sign-in again. */
  onReconnect?: (id: string) => void;
  /** `error`: try the handshake again. */
  onRetry?: (id: string) => void;
  /** Return a promise to show the button busy until it settles. Remove the server from `servers` to remove the row. */
  onDisconnect?: (id: string) => void | Promise<void>;
  /** Names the list for screen readers. */
  label?: string;
  className?: string;
};

/** The status line under a server's name. Connected servers show their tool count instead. */
const STATUS_TEXT: Record<ConnectionStatus, string> = {
  connected: "Connected",
  connecting: "Connecting…",
  "needs-auth": "Signed out",
  error: "Can’t connect",
  disabled: "Off",
};

const TOOL_LIMIT = 6;

function plural(n: number, one: string) {
  return `${n} ${n === 1 ? one : `${one}s`}`;
}

function said(server: Connection) {
  switch (server.status) {
    case "connected":
      return `${server.name} connected`;
    case "connecting":
      return `Connecting to ${server.name}`;
    case "needs-auth":
      return `${server.name} needs you to sign in again`;
    case "error":
      return `${server.name} can’t connect${server.message ? `: ${server.message}` : ""}`;
    case "disabled":
      return `${server.name} turned off`;
  }
}

/** Accepts "mcp.example.com" or a full URL; only https, except on localhost. */
export function parseServerUrl(raw: string, agent: string): { url: string; host: string } | { error: string } {
  const text = raw.trim();
  const notAddress = "That isn’t a web address. Try something like mcp.example.com.";
  if (!text) return { error: "Enter the server’s address, like mcp.example.com." };
  if (/\s/.test(text)) return { error: "Addresses can’t contain spaces. Check what you pasted." };
  let url: URL;
  try {
    url = new URL(/^[a-z][a-z\d+.-]*:\/\//i.test(text) ? text : `https://${text}`);
  } catch {
    return { error: notAddress };
  }
  const local = ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname);
  if (url.protocol !== "https:" && !(url.protocol === "http:" && local)) {
    return { error: `Use an https:// address. ${agent} only connects over HTTPS, except to localhost.` };
  }
  if (!local && !url.hostname.includes(".")) return { error: notAddress };
  if (url.username || url.password) return { error: "Leave the name and password out. You’ll sign in on the server’s own page." };
  url.hash = "";
  return { url: url.href, host: url.host };
}

function Mark({ server }: { server: Connection }) {
  return (
    <span className={styles.mark} aria-hidden="true">
      {server.mark ?? <span className={styles.initial}>{server.name.trim().charAt(0).toLocaleUpperCase()}</span>}
    </span>
  );
}

type RowProps = {
  server: Connection;
  agent: string;
  leaving: boolean;
  arrived: boolean;
  onToggle?: (id: string, on: boolean) => void;
  onReconnect?: (id: string) => void;
  onRetry?: (id: string) => void;
  onDisconnect?: (id: string) => void | Promise<void>;
  onLeaveWithFocus: (row: HTMLLIElement) => void;
  onGone: (id: string) => void;
};

function Row({ server, agent, leaving, arrived, onToggle, onReconnect, onRetry, onDisconnect, onLeaveWithFocus, onGone }: RowProps) {
  const baseId = useId();
  const panelId = `${baseId}-panel`;
  const metaId = `${baseId}-meta`;
  const rowRef = useRef<HTMLLIElement>(null);
  const disclosureRef = useRef<HTMLButtonElement>(null);
  const disconnectRef = useRef<HTMLButtonElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  const [showAll, setShowAll] = useState(false);

  const { name, status, tools, granted } = server;
  const toolCount = tools ? plural(tools.length, "tool") : null;
  const statusText = status === "connected" && toolCount ? toolCount : STATUS_TEXT[status];
  const action =
    status === "needs-auth" && onReconnect
      ? { label: "Sign in", name: `Sign in to ${name} again`, run: onReconnect }
      : status === "error" && onRetry
        ? { label: "Retry", name: `Retry ${name}`, run: onRetry }
        : null;

  // What went wrong, in full, at the top of the opened row.
  const notice =
    status === "error"
      ? { kind: "error" as const, text: server.message ?? `${name} didn’t answer. Check the address, or try again in a minute.` }
      : status === "needs-auth"
        ? { kind: "needs-auth" as const, text: server.message ?? `Your sign-in expired. ${agent} can’t use ${name} until you sign in again.` }
        : null;

  // The removed row is inert; take focus somewhere that stays.
  useLayoutEffect(() => {
    const row = rowRef.current;
    if (leaving && row?.contains(document.activeElement)) onLeaveWithFocus(row);
  }, [leaving, onLeaveWithFocus]);

  // Gone once its space has closed; the timer covers reduced motion and missed events.
  useEffect(() => {
    if (!leaving) return;
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const timer = window.setTimeout(() => onGone(server.id), reduce ? 0 : 700);
    return () => window.clearTimeout(timer);
  }, [leaving, onGone, server.id]);

  const wasConfirming = useRef(confirming);
  useLayoutEffect(() => {
    // The safe choice takes focus.
    if (confirming && !wasConfirming.current) cancelRef.current?.focus();
    wasConfirming.current = confirming;
  }, [confirming]);

  function toggleOpen() {
    setOpen((o) => !o);
    setConfirming(false);
    setFailure(null);
  }

  // The action leaves with the status that needed it; keep focus on this row.
  function act(fn?: (id: string) => void) {
    fn?.(server.id);
    requestAnimationFrame(() => {
      const active = document.activeElement;
      if (!active || active === document.body || active.closest("[inert]")) disclosureRef.current?.focus();
    });
  }

  function cancelConfirm() {
    setConfirming(false);
    setFailure(null);
    requestAnimationFrame(() => disconnectRef.current?.focus());
  }

  async function disconnect() {
    setFailure(null);
    const result = onDisconnect?.(server.id);
    if (!result || typeof result.then !== "function") return;
    setBusy(true);
    try {
      await result;
    } catch (reason) {
      setFailure(reason instanceof Error && reason.message ? reason.message : `${name} didn’t disconnect. Try again.`);
    }
    setBusy(false);
  }

  function onConfirmKey(event: KeyboardEvent) {
    if (event.key === "Escape" && !busy) {
      event.stopPropagation();
      cancelConfirm();
    }
  }

  const shownTools = tools && !showAll && tools.length > TOOL_LIMIT ? tools.slice(0, TOOL_LIMIT - 1) : tools;
  const hidden = tools ? tools.length - (shownTools?.length ?? 0) : 0;

  let toolsNote = "";
  if (status === "disabled") toolsNote = `Off. ${agent} can’t use these until you turn ${name} back on.`;
  else if (status === "needs-auth" && tools?.length) toolsNote = `${agent} can’t use these until you sign in again.`;

  return (
    <li
      ref={rowRef}
      className={styles.row}
      data-row-id={server.id}
      data-status={status}
      data-open={open}
      data-leaving={leaving || undefined}
      data-arrived={arrived || undefined}
      inert={leaving || undefined}
      onTransitionEnd={(e) => {
        if (leaving && e.target === e.currentTarget && e.propertyName === "grid-template-rows") onGone(server.id);
      }}
    >
      <div className={styles.rowClip}>
        <div className={styles.rowInner}>
          <div className={styles.head}>
            <Mark server={server} />
            <div className={styles.text}>
              <button
                ref={disclosureRef}
                type="button"
                className={styles.disclosure}
                data-row-disclosure
                aria-expanded={open}
                aria-controls={panelId}
                aria-describedby={metaId}
                onClick={toggleOpen}
              >
                <span className={styles.name}>{name}</span>
              </button>
              <span className={styles.meta} data-status={status}>
                <span id={metaId} className={status === "connecting" ? styles.sweep : undefined}>
                  <TextMorph>{statusText}</TextMorph>
                </span>
                {action && (
                  <>
                    <span className={styles.sep} aria-hidden="true">
                      ·
                    </span>
                    <button type="button" className={styles.action} aria-label={action.name} onClick={() => act(action.run)}>
                      {action.label}
                    </button>
                  </>
                )}
              </span>
            </div>
            <span className={styles.control}>
              <Switch
                aria-label={`Use ${name}`}
                checked={status !== "disabled"}
                onChange={(e) => onToggle?.(server.id, e.currentTarget.checked)}
              />
            </span>
          </div>

          <div id={panelId} className={styles.panel} data-open={open} inert={!open || undefined}>
            <div className={styles.clip}>
              <div className={styles.panelInner}>
                <div className={styles.about}>
                  <code className={styles.host}>{server.host}</code>
                  {notice && (
                    <p className={styles.problem} data-kind={notice.kind}>
                      {notice.text}
                    </p>
                  )}
                </div>
                <div className={styles.section}>
                  <span className={styles.sectionLabel} id={`${baseId}-tools`}>
                    Tools
                  </span>
                  {toolsNote && <p className={styles.sectionNote}>{toolsNote}</p>}
                  {!tools ? (
                    <p className={styles.sectionNote}>
                      {status === "connecting" ? `Tools show once ${name} answers.` : `No tools until ${name} answers.`}
                    </p>
                  ) : tools.length === 0 ? (
                    <p className={styles.sectionNote}>{name} doesn’t offer any tools yet.</p>
                  ) : (
                    <AnimatedSize>
                      <ul className={styles.tools} aria-labelledby={`${baseId}-tools`}>
                        {shownTools?.map((tool) => (
                          <li key={tool.name} className={styles.tool}>
                            <code className={styles.toolName}>{tool.name}</code>
                            {tool.description && <span className={styles.toolDescription}>{tool.description}</span>}
                          </li>
                        ))}
                      </ul>
                      {tools.length > TOOL_LIMIT && (
                        <Button variant="ghost" className={styles.more} onClick={() => setShowAll((s) => !s)}>
                          {showAll ? "Show fewer" : `Show ${hidden} more`}
                        </Button>
                      )}
                    </AnimatedSize>
                  )}
                </div>

                {(granted?.length || server.account) && (
                  <div className={styles.section}>
                    <span className={styles.sectionLabel} id={`${baseId}-granted`}>
                      Allowed when you signed in
                    </span>
                    {granted && granted.length > 0 && (
                      <ul className={styles.granted} aria-labelledby={`${baseId}-granted`}>
                        {granted.map((g) => (
                          <li key={g}>
                            <Icon name="check" className={styles.bullet} />
                            <span>{g}</span>
                          </li>
                        ))}
                      </ul>
                    )}
                    {server.account && (
                      <p className={styles.sectionNote}>
                        Signed in as <span className={styles.account}>{server.account}</span>
                      </p>
                    )}
                  </div>
                )}

                {onDisconnect && (
                  <AnimatedSize>
                    {confirming ? (
                      <div key="confirm" className={styles.confirm} data-enter role="group" aria-label={`Disconnect ${name}?`} onKeyDown={onConfirmKey}>
                        <p>
                          <strong>Disconnect {name}?</strong> {agent} loses {tools?.length ? `its ${plural(tools.length, "tool")}` : "access to it"}. To add it back,
                          you’ll sign in again.
                        </p>
                        {failure && (
                          <p className={styles.failure} role="alert">
                            {failure}
                          </p>
                        )}
                        <div className={styles.confirmActions}>
                          <Button ref={cancelRef} variant="secondary" onClick={cancelConfirm} disabled={busy}>
                            Cancel
                          </Button>
                          <Button variant="danger" busy={busy} busyLabel="Disconnecting…" onClick={disconnect}>
                            Disconnect
                          </Button>
                        </div>
                      </div>
                    ) : (
                      <div key="idle" className={styles.footer}>
                        <Button ref={disconnectRef} variant="secondary" onClick={() => setConfirming(true)}>
                          Disconnect
                        </Button>
                      </div>
                    )}
                  </AnimatedSize>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </li>
  );
}

function AddServer({
  agent,
  add,
  servers,
  onAdd,
  onCancelAdd,
  regionRef,
  inputRef,
  titleRef,
}: {
  agent: string;
  add: AddServerState;
  servers: Connection[];
  onAdd: (url: string) => void;
  onCancelAdd?: () => void;
  regionRef: RefObject<HTMLDivElement | null>;
  inputRef: RefObject<HTMLInputElement | null>;
  titleRef: RefObject<HTMLParagraphElement | null>;
}) {
  const [value, setValue] = useState("");
  const [localError, setLocalError] = useState<string | null>(null);
  // Closed to one "Add server" row until it's wanted; open when the list is
  // empty, since adding is then the only thing to do.
  const [opened, setOpened] = useState(false);
  const toggleRef = useRef<HTMLButtonElement>(null);
  const open = opened || servers.length === 0 || add.status !== "idle";

  // A finished add empties the field and closes it; a cancelled one keeps it.
  const [lastStatus, setLastStatus] = useState(add.status);
  const [lastCount, setLastCount] = useState(servers.length);
  if (lastStatus !== add.status || lastCount !== servers.length) {
    setLastStatus(add.status);
    setLastCount(servers.length);
    if (add.status === "idle" && lastStatus !== "failed" && lastStatus !== add.status) setValue("");
    if (add.status === "idle" && servers.length > lastCount) setOpened(false);
  }

  function openForm() {
    setOpened(true);
    requestAnimationFrame(() => inputRef.current?.focus());
  }

  function closeForm() {
    setOpened(false);
    setValue("");
    setLocalError(null);
    requestAnimationFrame(() => toggleRef.current?.focus());
  }

  function check(text: string) {
    const parsed = parseServerUrl(text, agent);
    if ("error" in parsed) return { error: parsed.error };
    const twin = servers.find((s) => s.host.toLowerCase() === parsed.host.toLowerCase());
    if (twin) return { error: `${twin.name} is already at ${parsed.host}.` };
    return { url: parsed.url };
  }

  // The server's error holds until the address is edited.
  const current = parseServerUrl(value, agent);
  const serverError = add.status === "failed" && "url" in current && current.url === add.url ? add.error : null;
  const error = localError ?? serverError;
  const checking = add.status === "checking";

  function submit(event: FormEvent) {
    event.preventDefault();
    if (checking) return;
    const result = check(value);
    if (result.error) {
      setLocalError(result.error);
      inputRef.current?.focus();
      return;
    }
    setLocalError(null);
    onAdd(result.url!);
  }

  const signingIn = add.status === "signing-in" ? add : null;
  const signInHost = signingIn ? new URL(signingIn.url).host : "";
  const signInName = signingIn?.name ?? signInHost;

  return (
    <div ref={regionRef} className={styles.add}>
      <AnimatedSize>
        {signingIn ? (
          <div key="signin" className={styles.signin} data-enter>
            <span className={styles.signinMark} aria-hidden="true">
              <Icon name="external" />
            </span>
            <div className={styles.signinText}>
              <p ref={titleRef} tabIndex={-1} className={styles.signinTitle}>
                Finish signing in in your browser
              </p>
              <p className={styles.signinNote}>
                {signInName}’s sign-in page should be open in a new tab. Allow {agent} there, and it will show up here.
              </p>
              <p className={styles.waiting}>
                <span className={styles.sweep}>Waiting for {signInHost}…</span>
              </p>
              <div className={styles.signinActions}>
                <ButtonLink href={signingIn.signInUrl} target="_blank" rel="noopener noreferrer">
                  Open sign-in page
                  <Icon name="external" />
                  <span className={styles.srOnly}> (opens in a new tab)</span>
                </ButtonLink>
                {onCancelAdd && (
                  <Button variant="secondary" onClick={onCancelAdd}>
                    Cancel
                  </Button>
                )}
              </div>
            </div>
          </div>
        ) : !open ? (
          <button key="toggle" ref={toggleRef} type="button" className={styles.addRow} onClick={openForm}>
            <span className={styles.addIcon} aria-hidden="true">
              <Icon name="plus" />
            </span>
            Add server
          </button>
        ) : (
          <form key="form" className={styles.form} onSubmit={submit} noValidate>
            <TextField
              ref={inputRef}
              label="Server address"
              hint="You’ll sign in to it in your browser."
              placeholder="mcp.example.com"
              type="url"
              inputMode="url"
              autoComplete="off"
              autoCapitalize="off"
              autoCorrect="off"
              spellCheck={false}
              value={value}
              readOnly={checking}
              error={error ?? null}
              onChange={(e) => {
                setValue(e.currentTarget.value);
                if (localError) setLocalError(check(e.currentTarget.value).error ?? null);
              }}
            />
            <div className={styles.formActions}>
              {servers.length > 0 && (
                <Button variant="ghost" onClick={closeForm} disabled={checking}>
                  Cancel
                </Button>
              )}
              <Button type="submit" busy={checking} busyLabel="Checking…">
                Add
              </Button>
            </div>
          </form>
        )}
      </AnimatedSize>
    </div>
  );
}

/** The MCP servers an agent is connected to: status, tools, what each was allowed, and adding more. */
export function Connections({
  servers,
  agent,
  add = { status: "idle" },
  onAdd,
  onCancelAdd,
  onToggle,
  onReconnect,
  onRetry,
  onDisconnect,
  label = "MCP servers",
  className,
}: ConnectionsProps) {
  const listRef = useRef<HTMLUListElement>(null);
  const addRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const titleRef = useRef<HTMLParagraphElement>(null);

  // Removed servers stay in place, inert, until their row has closed.
  const [previous, setPrevious] = useState(servers);
  const [leaving, setLeaving] = useState<{ server: Connection; index: number }[]>([]);
  const [arrived, setArrived] = useState<ReadonlySet<string>>(() => new Set());
  const [announcement, setAnnouncement] = useState("");
  const [previousAdd, setPreviousAdd] = useState(add.status);

  if (previous !== servers) {
    setPrevious(servers);
    const ids = new Set(servers.map((s) => s.id));
    const gone = previous.flatMap((server, index) => (ids.has(server.id) ? [] : [{ server, index }]));
    setLeaving((l) => [...l.filter((x) => !ids.has(x.server.id)), ...gone]);
    const fresh = servers.filter((s) => !previous.some((p) => p.id === s.id));
    if (fresh.length) setArrived((a) => new Set([...a, ...fresh.map((s) => s.id)]));

    const lines: string[] = [];
    for (const server of servers) {
      const before = previous.find((p) => p.id === server.id);
      if (!before) lines.push(server.status === "connected" ? `${server.name} added` : `${server.name} added. ${said(server)}`);
      else if (before.status !== server.status || (server.status === "error" && before.message !== server.message)) lines.push(said(server));
    }
    for (const { server } of gone) lines.push(`${server.name} disconnected`);
    if (lines.length) setAnnouncement(lines.join(". "));
  }

  if (previousAdd !== add.status) {
    setPreviousAdd(add.status);
    if (add.status === "checking") setAnnouncement(`Checking ${add.url}`);
  }

  const rows = servers.map((server) => ({ server, leaving: false }));
  for (const l of [...leaving].sort((a, b) => a.index - b.index)) {
    rows.splice(Math.min(l.index, rows.length), 0, { server: l.server, leaving: true });
  }

  // Focus follows the add flow: into the sign-in step, then to the new row,
  // or back to the field when it fails or is cancelled.
  const lastIds = useRef(servers.map((s) => s.id));
  const lastAdd = useRef(add.status);
  useLayoutEffect(() => {
    const ids = servers.map((s) => s.id);
    const fresh = ids.filter((id) => !lastIds.current.includes(id));
    lastIds.current = ids;
    const was = lastAdd.current;
    lastAdd.current = add.status;
    if (was === add.status) return;
    if (add.status === "signing-in") {
      titleRef.current?.focus();
      return;
    }
    const active = document.activeElement;
    const lost = !active || active === document.body || addRef.current?.contains(active);
    if (!lost || (was !== "checking" && was !== "signing-in")) return;
    if (add.status === "idle" && fresh.length) {
      listRef.current?.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(fresh.at(-1)!)}"] [data-row-disclosure]`)?.focus();
    } else {
      inputRef.current?.focus();
    }
  }, [servers, add.status]);

  const leaveWithFocus = useCallback((row: HTMLLIElement) => {
    const next = (from: Element | null, step: "nextElementSibling" | "previousElementSibling") => {
      for (let el = from?.[step] ?? null; el; el = el[step]) {
        if (!el.hasAttribute("data-leaving")) return el.querySelector<HTMLElement>("[data-row-disclosure]");
      }
      return null;
    };
    const target = next(row, "nextElementSibling") ?? next(row, "previousElementSibling") ?? inputRef.current;
    target?.focus();
  }, []);

  const gone = useCallback((id: string) => setLeaving((l) => l.filter((x) => x.server.id !== id)), []);

  const empty = rows.length === 0;

  return (
    <div className={className ? `${styles.root} ${className}` : styles.root}>
      {empty ? (
        <div className={styles.empty}>
          <p className={styles.emptyTitle}>No servers yet</p>
          <p className={styles.emptyNote}>Add an MCP server to give {agent} tools, like your bookings or payments.</p>
        </div>
      ) : (
        <ul ref={listRef} className={styles.list} aria-label={label}>
          {rows.map(({ server, leaving: isLeaving }) => (
            <Row
                key={server.id}
                server={server}
                agent={agent}
                leaving={isLeaving}
                arrived={arrived.has(server.id)}
                onToggle={onToggle}
                onReconnect={onReconnect}
                onRetry={onRetry}
                onDisconnect={onDisconnect}
                onLeaveWithFocus={leaveWithFocus}
                onGone={gone}
              />
          ))}
        </ul>
      )}

      {onAdd && (
        <AddServer
          agent={agent}
          add={add}
          servers={servers}
          onAdd={onAdd}
          onCancelAdd={onCancelAdd}
          regionRef={addRef}
          inputRef={inputRef}
          titleRef={titleRef}
        />
      )}

      <span role="status" className={styles.srOnly}>
        {announcement}
      </span>
    </div>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* ---------- Trigger ---------- */

  .trigger {
    --trigger-pad-start: 14px;
    --trigger-pad-end: 10px;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);

    position: relative;
    display: inline-flex;
    align-items: center;
    flex-shrink: 0;
    height: var(--ui-control-sm);
    padding: 0 var(--trigger-pad-end) 0 var(--trigger-pad-start);
    border: 0;
    border-radius: var(--ui-radius-full);
    background: none;
    color: var(--ui-muted);
    isolation: isolate;
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      width var(--ui-dur-move) var(--ui-ease-move),
      color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* No press scale: the list is anchored to the trigger's real box. */
  .trigger::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: transparent;
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .trigger:hover:not(:disabled) {
      color: var(--ui-foreground);
    }
    .trigger:hover:not(:disabled)::before {
      background: var(--ui-fill);
    }
  }

  .trigger[aria-expanded="true"] {
    color: var(--ui-foreground);
  }

  .trigger[aria-expanded="true"]::before {
    background: var(--ui-fill);
  }

  .trigger:active:not(:disabled)::before {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  .trigger:focus-visible:not([data-pointer-focus]) {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .trigger:disabled {
    opacity: 0.5;
    cursor: default;
  }

  .content {
    display: inline-flex;
    align-items: center;
    gap: 6px;
  }

  /* Must keep the trigger's padding, since its width becomes the trigger's. */
  .measure {
    position: absolute;
    top: 0;
    left: 0;
    padding: 0 var(--trigger-pad-end) 0 var(--trigger-pad-start);
    visibility: hidden;
    pointer-events: none;
  }

  .chevron {
    display: inline-block;
    flex-shrink: 0;
    width: var(--ui-icon-chevron);
    height: var(--ui-icon-chevron);
    color: var(--ui-subtle);
  }

  @media (pointer: coarse) {
    .trigger::after {
      content: "";
      position: absolute;
      inset: -4px;
    }
  }

  /* ---------- List ---------- */

  /* Base UI's Positioner places this element; .surface animates inside it. */
  .positioner {
    z-index: 50;
    min-width: 240px;
    max-width: min(300px, calc(100vw - 16px));
    outline: none;
  }

  .surface {
    position: relative;
    box-sizing: border-box;
    max-height: min(calc(100dvh - 16px), var(--available-height, 100dvh));
    /* Rows sit one inset in and take the concentric radius: rounded, not pills. */
    --menu-inset: var(--ui-inset-menu);
    --menu-row-radius: calc(var(--ui-radius-lg) - var(--menu-inset));
    padding: var(--menu-inset);
    overflow-y: auto;
    overscroll-behavior: contain;
    border-radius: var(--ui-radius-lg);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-floating);
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    user-select: none;
    outline: none;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    transform-origin: var(--transform-origin);
    opacity: 1;
    scale: 1;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .surface[data-starting-style],
  .surface[data-ending-style] {
    opacity: 0;
    scale: 0.97;
  }

  .surface[data-ending-style] {
    transition-duration: var(--ui-dur-instant);
    transition-timing-function: var(--ui-ease-exit);
  }

  .highlight {
    position: absolute;
    top: 0;
    left: var(--menu-inset);
    right: var(--menu-inset);
    border-radius: var(--menu-row-radius);
    background: var(--ui-fill-strong);
    opacity: 0;
    pointer-events: none;
    transition:
      translate var(--ui-dur-snap) var(--ui-ease-snap),
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .highlight[data-visible] {
    opacity: 1;
  }

  .highlight[data-jump] {
    transition-property: opacity, background-color;
  }

  .surface:has(.option:active:not([data-disabled])) > .highlight {
    background: color-mix(in oklch, var(--ui-foreground) 16%, transparent);
    transition-duration: var(--ui-dur-press);
  }

  .option {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-3);
    padding: var(--ui-space-2) var(--ui-pad-row);
    border-radius: var(--menu-row-radius);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }

  .option {
    outline: none;
  }

  .option[data-disabled] {
    cursor: default;
  }

  .option[data-disabled] .name {
    color: var(--ui-subtle);
  }

  .text {
    display: grid;
    flex: 1;
    min-width: 0;
  }

  .name {
    font-weight: var(--ui-weight-medium);
  }

  .description {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .check {
    flex-shrink: 0;
    width: 16px;
    height: 16px;
    margin-top: calc((var(--ui-leading-md) - 16px) / 2);
    stroke-width: var(--ui-icon-stroke);
    overflow: visible;
  }

  /* With pathLength 1, offset 1.3 hides the stroke including its round cap. */
  .check path {
    stroke-dasharray: 1 3;
    stroke-dashoffset: 1.3;
    transition: stroke-dashoffset var(--ui-dur-fast) var(--ui-ease-exit);
  }

  .check[data-drawn] path {
    stroke-dashoffset: 0;
    transition: stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw);
  }

  @media (pointer: coarse) {
    .option {
      min-height: 44px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger {
      transition-property: color;
    }
    .surface {
      transition: none;
    }
    .surface[data-starting-style],
    .surface[data-ending-style] {
      scale: none;
    }
    .highlight {
      transition-property: opacity, background-color;
    }
    .check path,
    .check[data-drawn] path {
      transition: none;
    }
  }
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { Select } from "@base-ui/react/select";
import { Icon } from "../icons/icons";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./model-picker.module.css";

type Side = "top" | "bottom" | "left" | "right";
type Align = "start" | "center" | "end";

export type ModelOption = {
  id: string;
  /** Shown on the trigger. */
  name: string;
  description: string;
  /** Shown but can't be picked. */
  disabled?: boolean;
};

type ModelPickerProps = {
  models: ModelOption[];
  value: string;
  onValueChange: (id: string) => void;
  /** Accessible name of the trigger and list. */
  label?: string;
  side?: Side;
  align?: Align;
  disabled?: boolean;
  className?: string;
};

/** Slides one rounded fill under whichever option Base UI marks `data-highlighted`. */
function useHighlightBar(popup: HTMLElement | null) {
  const barRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const bar = barRef.current;
    if (!popup || !bar) return;
    function place() {
      if (!bar || !popup) return;
      const option = popup.querySelector<HTMLElement>('[role="option"][data-highlighted]');
      if (!option) {
        bar.removeAttribute("data-visible");
        return;
      }
      const jump = !bar.hasAttribute("data-visible");
      if (jump) bar.setAttribute("data-jump", "");
      bar.style.translate = `0 ${option.offsetTop}px`;
      bar.style.height = `${option.offsetHeight}px`;
      bar.setAttribute("data-visible", "");
      if (jump) {
        bar.getBoundingClientRect();
        bar.removeAttribute("data-jump");
      }
    }
    place();
    const observer = new MutationObserver(place);
    observer.observe(popup, { subtree: true, attributes: true, attributeFilter: ["data-highlighted"] });
    return () => observer.disconnect();
  }, [popup]);
  return barRef;
}

export function ModelPicker({
  models,
  value,
  onValueChange,
  label = "Model",
  side = "bottom",
  align = "start",
  disabled = false,
  className,
}: ModelPickerProps) {
  const id = useId();
  const descriptionId = (modelId: string) => `${id}-${modelId}-description`;
  const selected = models.find((m) => m.id === value) ?? models[0];

  const measureRef = useRef<HTMLSpanElement>(null);
  const [trigger, setTrigger] = useState<HTMLButtonElement | null>(null);
  const [popup, setPopup] = useState<HTMLDivElement | null>(null);
  const [open, setOpen] = useState(false);
  const [width, setWidth] = useState<number | null>(null);
  const barRef = useHighlightBar(popup);

  // An explicit px width lets the trigger transition between label widths.
  useLayoutEffect(() => {
    const el = measureRef.current;
    if (!el) return;
    const measure = () => setWidth(Math.ceil(el.getBoundingClientRect().width));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [selected?.name]);

  return (
    <Select.Root
      value={selected?.id ?? null}
      onValueChange={(next) => {
        if (typeof next === "string" && next !== value) onValueChange(next);
      }}
      open={open}
      onOpenChange={setOpen}
      disabled={disabled}
      modal={false}
    >
      <Select.Trigger
        ref={setTrigger}
        className={className ? `${styles.trigger} ${className}` : styles.trigger}
        style={{ width: width ?? undefined }}
        aria-label={`${label}: ${selected?.name ?? "None"}`}
      >
        <span className={styles.content} aria-hidden="true">
          <TextMorph>{selected?.name ?? ""}</TextMorph>
          <Icon className={styles.chevron} name={open ? "chevron-up" : "chevron-down"} />
        </span>
        <span ref={measureRef} className={`${styles.content} ${styles.measure}`} aria-hidden="true">
          <span>{selected?.name}</span>
          <span className={styles.chevron} />
        </span>
      </Select.Trigger>
      <Select.Portal container={trigger?.closest<HTMLElement>("dialog[open], [data-theme]") ?? undefined}>
        <Select.Positioner
          className={styles.positioner}
          side={side}
          align={align}
          sideOffset={8}
          collisionPadding={8}
          alignItemWithTrigger={false}
        >
          <Select.Popup ref={setPopup} className={styles.surface} aria-label={label}>
            <span ref={barRef} className={styles.highlight} aria-hidden="true" />
            {models.map((model) => {
              const isSelected = model.id === selected?.id;
              return (
                <Select.Item
                  key={model.id}
                  value={model.id}
                  label={model.name}
                  disabled={model.disabled}
                  aria-describedby={descriptionId(model.id)}
                  className={styles.option}
                >
                  <span className={styles.text}>
                    <Select.ItemText className={styles.name}>{model.name}</Select.ItemText>
                    <span id={descriptionId(model.id)} className={styles.description}>
                      {model.description}
                    </span>
                  </span>
                  <DrawnCheck drawn={isSelected} />
                </Select.Item>
              );
            })}
          </Select.Popup>
        </Select.Positioner>
      </Select.Portal>
    </Select.Root>
  );
}

function DrawnCheck({ drawn }: { drawn: boolean }) {
  return (
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      fill="none"
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      className={styles.check}
      data-drawn={drawn || undefined}
    >
      <path d="M3.75 8.25 6.75 11.25 12.25 5" pathLength={1} />
    </svg>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* Shared field parts to compose. */

  .field {
    display: grid;
    /* The field's width, not its input's: an input's default size (about 20
       characters) would otherwise push a narrow form sideways. */
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ui-space-2);
    min-width: 0;
    font-family: var(--ui-font-sans);
  }

  .label {
    justify-self: start;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .shell {
    --edge: var(--ui-border-strong);
    --edge-width: var(--ui-hairline);
    --shell-inset: calc((var(--ui-control-md) - var(--ui-control-sm)) / 2);
    position: relative;
    height: var(--ui-control-md);
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition: box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .shell:hover:not(:focus-within, [data-invalid], [data-disabled], [data-open]) {
      --edge: var(--ui-field-focus);
    }
  }

  .shell:focus-within,
  .shell[data-open] {
    --edge: var(--ui-field-focus);
    --edge-width: 1px;
    box-shadow: inset 0 0 0 var(--edge-width) var(--edge);
    transition-duration: 0s;
  }

  .shell[data-open] {
    transition-duration: var(--ui-dur-instant);
  }

  .shell[data-invalid] {
    --edge: var(--ui-danger);
  }

  .shell[data-disabled] {
    opacity: 0.5;
  }

  .bare {
    min-width: 0;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    outline: none;
  }

  .bare::placeholder {
    color: var(--ui-subtle);
  }

  .bare:disabled {
    cursor: default;
  }

  /* iOS zooms the page into any field under 16px. */
  @media (pointer: coarse) {
    .bare {
      font-size: var(--ui-text-touch);
    }
  }

  /* Inset button. Set its radius where it sits (outer radius less the inset). */
  .inset {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    position: relative;
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: var(--ui-control-sm);
    height: var(--ui-control-sm);
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-md) - var(--shell-inset, 4px));
    background: none;
    color: var(--ui-muted);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .inset::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .inset > * {
    position: relative;
  }

  @media (hover: hover) {
    .inset:hover:not(:disabled, [aria-disabled]) {
      color: var(--ui-foreground);
    }
    .inset:hover:not(:disabled, [aria-disabled])::before {
      background: var(--ui-fill);
    }
  }

  .inset:active:not(:disabled, [aria-disabled]) {
    color: var(--ui-foreground);
  }

  .inset:active:not(:disabled, [aria-disabled])::before {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .inset:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
    color: var(--ui-foreground);
  }

  .inset:disabled,
  .inset[aria-disabled] {
    cursor: default;
  }

  /* 32px to look at, 40px to hit. */
  @media (pointer: coarse) {
    .inset::after {
      content: "";
      position: absolute;
      inset: -4px;
    }
  }

  .message {
    display: grid;
    min-height: var(--ui-leading-md);
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .hint,
  .error {
    grid-area: 1 / 1;
    min-width: 0;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .hint[data-shown],
  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  .hint {
    color: var(--ui-muted);
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    color: var(--ui-danger-text);
  }

  .errorIcon {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    --ui-icon-stroke: calc(var(--ui-icon-stroke-regular) * 16 / 14);
  }

  .error[data-shown] .errorText {
    animation: field-error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes field-error-swap {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .inset:active:not(:disabled, [aria-disabled])::before {
      scale: none;
    }
    .error[data-shown] .errorText {
      animation: none;
    }
  }
}

"use client";

import { useState } from "react";
import { Icon } from "../icons/icons";
import styles from "./field.module.css";

type FieldMessageProps = {
  id: string;
  hint?: string | null;
  error?: string | null;
};

/** Hint or error; the hidden one leaves the description and live region. */
export function FieldMessage({ id, hint, error }: FieldMessageProps) {
  const [lastError, setLastError] = useState(error);
  if (error && error !== lastError) setLastError(error);

  return (
    <p id={id} className={styles.message} aria-live="polite">
      {hint && (
        <span className={styles.hint} data-shown={!error || undefined}>
          {hint}
        </span>
      )}
      {lastError && (
        <span className={styles.error} data-shown={error ? true : undefined}>
          <Icon name="alert" className={styles.errorIcon} />
          <span key={lastError} className={styles.errorText}>
            {lastError}
          </span>
        </span>
      )}
    </p>
  );
}

@layer theme, base, components, utilities;

.field {
  composes: field from "../field/field.module.css";
}

.label {
  composes: label from "../field/field.module.css";
}

.control {
  composes: shell from "../field/field.module.css";
}

/* ---------- Buttons ---------- */
.step {
  composes: inset from "../field/field.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .field {
    --number-width: 136px;
    justify-items: start;
  }

  .control {
    display: grid;
    grid-template-columns: var(--ui-control-sm) minmax(0, 1fr) var(--ui-control-sm);
    align-items: center;
    gap: 2px;
    width: var(--number-width);
    max-width: 100%;
    padding-inline: var(--shell-inset);
    cursor: text;
  }

  .control:not([data-steppers]) {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0;
    padding-inline: calc(var(--shell-inset) + var(--ui-space-2));
  }

  .control:not([data-steppers]) :is(.input, .morph) {
    text-align: start;
    justify-items: start;
  }

  .affix {
    color: var(--ui-muted);
    font-size: var(--ui-text-md);
    font-variant-numeric: tabular-nums;
    line-height: var(--ui-leading-md);
    white-space: pre;
    user-select: none;
  }

  .step:is([aria-disabled], [data-disabled]) {
    opacity: 0.4;
  }

  @media (pointer: coarse) {
    .step.step::after {
      inset: calc(var(--shell-inset) * -1);
    }
  }

  /* ---------- Number ---------- */

  /* Input and morph layer must share one cell and alignment so the caret lands on the digits. */
  .value {
    position: relative;
    display: grid;
    min-width: 0;
    height: 100%;
  }

  .input,
  .morph {
    grid-area: 1 / 1;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-regular);
    font-variant-numeric: tabular-nums;
    line-height: var(--ui-leading-md);
    text-align: center;
  }

  .input {
    width: 100%;
    min-width: 0;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: transparent;
    font-family: inherit;
    outline: none;
  }

  .input[data-editing] {
    color: var(--ui-foreground);
  }

  .input::selection {
    background: var(--ui-selection);
  }

  .input:disabled {
    cursor: default;
  }

  .morph {
    display: grid;
    place-items: center;
    overflow: hidden;
    color: var(--ui-foreground);
    white-space: pre;
    pointer-events: none;
  }

  .digits {
    display: inline-flex;
  }

  /* Transform and opacity only, so a change moves no box. Digits that stay
     aren't remounted and don't animate. */
  .digit {
    display: inline-block;
  }

  .digit[data-changed] {
    animation: number-digit-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .digits[data-dir="up"] {
    --digit-from: 0.25em;
  }

  .digits[data-dir="down"] {
    --digit-from: -0.25em;
  }

  @keyframes number-digit-in {
    from {
      opacity: 0;
      translate: 0 var(--digit-from);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .digit[data-changed] {
      animation-name: number-digit-fade;
    }
  }

  @keyframes number-digit-fade {
    from {
      opacity: 0;
    }
  }

  /* iOS zooms the page into any field under 16px. */
  @media (pointer: coarse) {
    .input,
    .morph,
    .affix {
      font-size: var(--ui-text-touch);
    }
  }
}

"use client";

import { useId, useMemo, useRef, useState, type KeyboardEvent, type Ref } from "react";
import { NumberField } from "@base-ui/react/number-field";
import { FieldMessage } from "../field/field";
import { Icon } from "../icons/icons";
import styles from "./number-input.module.css";

type NumberInputProps = {
  label: string;
  /** Keeps `label` as the field's name but doesn't show it, for a row whose own text already says it. */
  hideLabel?: boolean;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  /** One press or arrow key; Shift, PageUp and PageDown move ten. */
  step?: number;
  /** E.g. `{ style: "currency", currency: "USD" }`. */
  format?: Intl.NumberFormatOptions;
  locale?: string;
  hint?: string;
  error?: string | null;
  name?: string;
  disabled?: boolean;
  /** `false` hides the − and + buttons, e.g. for money. */
  steppers?: boolean;
  /** With `steppers={false}`, `false` also turns off the stepping keys. */
  arrowKeys?: boolean;
  id?: string;
  className?: string;
  ref?: Ref<HTMLInputElement>;
};

/** Changes that come from typing; the field commits them on blur or Enter. */
const TYPING = new Set(["input-change", "input-clear", "input-paste"]);
const STEP_KEYS = new Set(["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End"]);

const decimals = (n: number) => {
  if (!Number.isFinite(n)) return 0;
  const s = String(n);
  const e = s.indexOf("e-");
  if (e !== -1) return Number(s.slice(e + 2));
  const dot = s.indexOf(".");
  return dot === -1 ? 0 : s.length - dot - 1;
};

function affixes(parts: Intl.NumberFormatPart[]) {
  const digitsAt = parts.findIndex((p) => p.type === "integer" || p.type === "nan" || p.type === "infinity");
  let prefix = "";
  let suffix = "";
  parts.forEach((p, i) => {
    const affix = p.type === "currency" || p.type === "unit" || (p.type === "literal" && !p.value.trim());
    if (!affix) return;
    if (i < digitsAt) prefix += p.value;
    else suffix += p.value;
  });
  return { prefix, suffix };
}

/** Sets an input's text the way typing does, so Base UI sees it as a change. */
function setText(input: HTMLInputElement, text: string) {
  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")?.set;
  setter?.call(input, text);
  input.dispatchEvent(new Event("input", { bubbles: true }));
}

/**
 * The shown number. Each character is keyed by its place from the right, so a
 * step remounts only the digits that changed, and those rise into place by a
 * few pixels. Nothing animates width or position: in tabular figures the kept
 * digits never move, and the field's box never changes.
 */
function Digits({ text, value }: { text: string; value: number }) {
  // Starts still: a remount (after typing, say) shows the number as it is.
  const [last, setLast] = useState({ text, value, previous: text, dir: 0 });
  if (last.text !== text) setLast({ text, value, previous: last.text, dir: Math.sign(value - last.value) || 1 });
  const chars = Array.from(text);
  const before = Array.from(last.previous);
  return (
    <span className={styles.digits} data-dir={last.dir > 0 ? "up" : "down"}>
      {chars.map((char, i) => {
        const place = chars.length - i;
        const changed = last.dir !== 0 && before[before.length - place] !== char;
        return (
          <span key={`${place}:${char}`} className={styles.digit} data-changed={changed || undefined}>
            {char}
          </span>
        );
      })}
    </span>
  );
}

/** Base UI's NumberField with − and + buttons, a rolling value, and a note when typing is pulled into range. */
export function NumberInput({
  label,
  hideLabel = false,
  value: controlledValue,
  defaultValue,
  onValueChange,
  min,
  max,
  step = 1,
  format,
  locale,
  hint,
  error,
  name,
  disabled = false,
  steppers = true,
  arrowKeys = true,
  id,
  className,
  ref,
}: NumberInputProps) {
  const fallbackId = useId();
  const inputId = id ?? fallbackId;
  const messageId = `${inputId}-message`;
  const affixId = `${inputId}-affix`;
  const stepKeys = steppers || arrowKeys;

  const lo = min ?? -Infinity;
  const hi = max ?? Infinity;
  const clamp = (n: number) => Math.min(Math.max(n, lo), hi);

  const [uncontrolledValue, setUncontrolledValue] = useState(() => clamp(defaultValue ?? (Number.isFinite(lo) ? lo : 0)));
  const value = controlledValue ?? uncontrolledValue;

  const full = useMemo(() => new Intl.NumberFormat(locale, format), [locale, format]);
  // Values keep as many decimals as the step, the minimum or the format shows, so typed cents survive a step of 1.
  const precision = Math.min(
    20,
    Math.max(decimals(step), decimals(Number.isFinite(lo) ? lo : 0), full.resolvedOptions().minimumFractionDigits ?? 0),
  );
  // Without steppers, a currency symbol or unit sits outside the input, so the input formats the digits alone.
  const pinned = !steppers && (format?.style === "currency" || format?.style === "unit");
  const fieldFormat = useMemo<Intl.NumberFormatOptions>(() => {
    if (pinned) {
      const r = full.resolvedOptions();
      return {
        minimumFractionDigits: r.minimumFractionDigits,
        maximumFractionDigits: r.maximumFractionDigits,
        useGrouping: r.useGrouping as Intl.NumberFormatOptions["useGrouping"],
      };
    }
    return { maximumFractionDigits: precision, ...format };
  }, [pinned, full, precision, format]);
  const formatter = useMemo(() => new Intl.NumberFormat(locale, fieldFormat), [locale, fieldFormat]);
  const decimalMark = useMemo(
    () => new Intl.NumberFormat(locale).formatToParts(1.5).find((p) => p.type === "decimal")?.value ?? ".",
    [locale],
  );

  const number = formatter.format(value);
  const { prefix, suffix } = useMemo(
    () => (pinned ? affixes(full.formatToParts(value)) : { prefix: "", suffix: "" }),
    [pinned, full, value],
  );

  const [editing, setEditing] = useState(false);
  const [note, setNote] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const typed = useRef<number | null>(null);

  const round = (n: number) => Number(n.toFixed(precision));

  function commit(next: number) {
    if (controlledValue === undefined) setUncontrolledValue(next);
    if (next !== value) onValueChange?.(next);
  }

  function parse(text: string) {
    const cleaned = text
      .split(decimalMark)
      .map((part) => part.replace(/[^\d-]/g, ""))
      .join(".");
    if (!/\d/.test(cleaned)) return null;
    const n = Number(cleaned.replace(/(?!^)-/g, ""));
    return Number.isFinite(n) ? n : null;
  }

  function noteFor(clamped: number, raw: number | null) {
    if (raw === null) return null;
    if (clamped > raw) return `At least ${full.format(clamped)}`;
    if (clamped < raw) return `Up to ${full.format(clamped)}`;
    return null;
  }

  function onKeyDown(event: KeyboardEvent<HTMLInputElement> & { preventBaseUIHandler?: () => void }) {
    const input = event.currentTarget;
    if (!stepKeys && STEP_KEYS.has(event.key)) {
      // A plain text box: the keys move the caret, nothing steps.
      event.preventBaseUIHandler?.();
      return;
    }
    switch (event.key) {
      case "PageUp":
      case "PageDown": {
        // Base UI leaves these to the browser; they move ten steps, as Shift+Arrow does.
        event.preventDefault();
        const key = event.key === "PageUp" ? "ArrowUp" : "ArrowDown";
        input.dispatchEvent(new globalThis.KeyboardEvent("keydown", { key, shiftKey: true, bubbles: true, cancelable: true }));
        return;
      }
      case "Enter": {
        if (!editing) return;
        const raw = parse(input.value);
        const next = raw === null ? value : clamp(round(raw));
        setText(input, formatter.format(next));
        setEditing(false);
        setNote(noteFor(next, raw));
        commit(next);
        return;
      }
      case "Escape":
        if (!editing) return;
        event.preventDefault();
        setText(input, number);
        setEditing(false);
        setNote(null);
        return;
    }
  }

  const message = error ?? note ?? hint;
  const hasMessage = Boolean(hint || error !== undefined || Number.isFinite(lo) || Number.isFinite(hi));

  return (
    <NumberField.Root
      id={inputId}
      className={className ? `${styles.field} ${className}` : styles.field}
      value={value}
      min={min}
      max={max}
      step={step}
      smallStep={step}
      largeStep={step * 10}
      format={fieldFormat}
      locale={locale}
      name={name}
      disabled={disabled}
      inputRef={ref}
      onValueChange={(next, details) => {
        if (TYPING.has(details.reason)) return;
        setEditing(false);
        if (next === null) return;
        setNote(details.reason === "input-blur" ? noteFor(next, typed.current) : null);
        typed.current = null;
        commit(next);
      }}
    >
      <label className={hideLabel ? styles.srOnly : styles.label} htmlFor={inputId}>
        {label}
      </label>
      <NumberField.Group
        className={styles.control}
        data-invalid={error ? "" : undefined}
        data-steppers={steppers || undefined}
        onPointerDown={(event) => {
          const target = event.target as HTMLElement;
          if (disabled || target.closest("button") || target === inputRef.current) return;
          event.preventDefault();
          inputRef.current?.focus();
        }}
      >
        {steppers ? (
          <NumberField.Decrement
            className={styles.step}
            aria-label={`Decrease ${label}`}
            // Base UI writes aria-disabled="false"; the shared inset style reads the attribute's presence.
            aria-disabled={disabled || value <= lo || undefined}
          >
            <Icon name="minus" />
          </NumberField.Decrement>
        ) : (
          <span className={styles.affix} aria-hidden="true">
            {prefix}
          </span>
        )}
        <div className={styles.value}>
          <NumberField.Input
            ref={inputRef}
            className={styles.input}
            data-editing={editing || undefined}
            aria-invalid={error ? true : undefined}
            // The affix is aria-hidden, so it is read as a description after the digits.
            aria-describedby={
              [pinned && (prefix || suffix) ? affixId : "", hasMessage && message ? messageId : ""].filter(Boolean).join(" ") ||
              undefined
            }
            onChange={(event) => {
              setEditing(true);
              setNote(null);
              typed.current = parse(event.currentTarget.value);
            }}
            onKeyDown={onKeyDown}
            onBlur={() => setEditing(false)}
          />
          {!editing && (
            <span className={styles.morph} aria-hidden="true">
              <Digits text={number} value={value} />
            </span>
          )}
        </div>
        {steppers ? (
          <NumberField.Increment
            className={styles.step}
            aria-label={`Increase ${label}`}
            aria-disabled={disabled || value >= hi || undefined}
          >
            <Icon name="plus" />
          </NumberField.Increment>
        ) : (
          <span className={styles.affix} aria-hidden="true">
            {suffix}
          </span>
        )}
        {pinned && (prefix || suffix) && (
          <span id={affixId} hidden>
            {`${prefix}${suffix}`.trim()}
          </span>
        )}
      </NumberField.Group>
      {hasMessage && <FieldMessage id={messageId} hint={note ?? hint} error={error} />}
    </NumberField.Root>
  );
}

/* The pill's flight from one item to the next, shared by Tabs and the
   Segmented control so the two move as one family. The resting position is
   the caller's; this plays the move between two spans on top of it. */

/** A pill's offset and length along its track, and how far it's dipped. */
export type PillSpan = { start: number; length: number; dip?: number };

/** How deep the pill dips mid-flight, in px: none. A dip (and a spring on
 *  the leading edge) read as organic, a blob more than a control. */
const MAX_DIP = 0;

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

/** A `linear(...)` easing token as a function of progress, for sampling in JS. */
function curve(value: string): (t: number) => number {
  const points = value.startsWith("linear(") ? value.slice(7, -1).split(",").map(parseFloat) : [];
  if (points.length < 2 || points.some(Number.isNaN)) return (t) => 1 - (1 - t) ** 3;
  return (t) => {
    const at = Math.min(Math.max(t, 0), 1) * (points.length - 1);
    const i = Math.min(Math.floor(at), points.length - 2);
    return points[i] + (points[i + 1] - points[i]) * (at - i);
  };
}

/** Where the pill is along its track right now, mid-animation included. */
function translated(el: HTMLElement, vertical: boolean) {
  const transform = getComputedStyle(el).transform;
  if (!transform || transform === "none") return 0;
  const matrix = new DOMMatrixReadOnly(transform);
  return vertical ? matrix.m42 : matrix.m41;
}

/** Stops a flight in progress and returns where it left the pill on screen, or null if it was still. */
export function stopPill(indicator: HTMLElement, vertical = false): PillSpan | null {
  const running = indicator.getAnimations();
  if (!running.length) return null;
  const box = indicator.getBoundingClientRect();
  const span = {
    start: translated(indicator, vertical),
    length: vertical ? box.height : box.width,
    dip: Math.max(0, vertical ? indicator.offsetWidth - box.width : indicator.offsetHeight - box.height),
  };
  running.forEach((a) => a.cancel());
  return span;
}

/**
 * Flies the pill from one span to another: the edge facing the new item
 * leads, the far edge follows, both on the glide (no overshoot), so the
 * pill stretches a little toward the new item and settles once. Length
 * animates, not scale, which would squash the round ends. Under reduced
 * motion it doesn't play.
 */
export function flyPill(indicator: HTMLElement, from: PillSpan, to: PillSpan, vertical = false) {
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const duration = ms(token(indicator, "--ui-dur-glide", "320ms"));
  const lead = curve(token(indicator, "--ui-ease-glide", ""));
  const follow = curve(token(indicator, "--ui-ease-glide", ""));
  const leadShare = ms(token(indicator, "--ui-dur-snap", "250ms")) / duration;
  const forward = to.start > from.start;
  const fromDip = from.dip ?? 0;
  // The dip only ever shrinks the pill, so nothing pokes out of the track.
  const full = vertical ? indicator.offsetWidth : indicator.offsetHeight;
  const travel = Math.abs(to.start + to.length / 2 - (from.start + from.length / 2));
  const dip = Math.min(MAX_DIP, travel / 30);
  const frames: Keyframe[] = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const fast = lead(Math.min(t / leadShare, 1));
    const slow = follow(t);
    const near = from.start + (to.start - from.start) * (forward ? slow : fast);
    const far = from.start + from.length + (to.start + to.length - from.start - from.length) * (forward ? fast : slow);
    const p = Math.min(Math.max((fast + slow) / 2, 0), 1);
    const d = fromDip * (1 - p) + dip * Math.sin(Math.PI * p);
    frames.push(
      vertical
        ? { transform: `translate(${d / 2}px, ${near}px)`, height: `${far - near}px`, width: `${full - d}px` }
        : { transform: `translate(${near}px, ${d / 2}px)`, width: `${far - near}px`, height: `${full - d}px` },
    );
  }
  indicator.animate(frames, { duration, easing: "linear" });
}

@layer theme, base, components, utilities;

.pause {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .tabs {
    display: grid;
    gap: var(--ui-space-4);
    min-width: 0;
    font-family: var(--ui-font-sans);
  }

  .list {
    position: relative;
    isolation: isolate;
    display: flex;
    justify-self: start;
    max-width: 100%;
    /* The track the Segmented control shares: --ui-track-* in the tokens. */
    padding: var(--ui-track-inset);
    border-radius: var(--ui-radius-full);
    box-shadow: var(--ui-track-edge);
    overflow-x: auto;
    /* Also blocks the browser's back-swipe gesture. */
    overscroll-behavior-inline: none;
    /* Keeps a selected tab scrolled clear of the edge fade. */
    scroll-padding-inline: var(--ui-space-6);
    scrollbar-width: none;
  }

  .list::-webkit-scrollbar {
    display: none;
  }

  .list[data-overflow-end] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .list[data-overflow-start] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  :is([dir="rtl"]) .list[data-overflow-end] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  :is([dir="rtl"]) .list[data-overflow-start] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .list[data-overflow-start][data-overflow-end] {
    mask-image: linear-gradient(
      to right,
      transparent,
      black var(--ui-space-6),
      black calc(100% - var(--ui-space-6)),
      transparent
    );
  }

  /* Base UI's Indicator places it on the selected tab through its CSS
     variables; the flight between tabs is a script animation on top. */
  .indicator {
    position: absolute;
    top: var(--ui-track-inset);
    left: 0;
    z-index: -1;
    width: var(--active-tab-width);
    height: var(--ui-control-sm);
    border-radius: var(--ui-radius-full);
    background: var(--ui-track-pill);
    transform: translateX(var(--active-tab-left));
    contain: strict;
    pointer-events: none;
  }

  .tab {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    flex-shrink: 0;
    height: var(--ui-control-sm);
    padding-inline: 14px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: transparent;
    color: var(--ui-muted);
    /* One weight for every state: bolding the selected tab would widen it. */
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .tab[data-active] {
    color: var(--ui-foreground);
  }

  /* Until the Indicator has measured, the selected tab carries the pill itself. */
  .list:not(:has(> .indicator:not([hidden]))) .tab[data-active] {
    background: var(--ui-track-pill);
  }

  @media (hover: hover) {
    .tab:hover:not([data-active]) {
      color: var(--ui-foreground);
    }
  }

  .tab:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .tab svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    pointer-events: none;
  }

  /* ---------- Count ---------- */

  .count {
    color: var(--ui-subtle);
    font-weight: var(--ui-weight-regular);
    font-variant-numeric: tabular-nums;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .tab[data-active] .count {
    color: var(--ui-muted);
  }

  @media (hover: hover) {
    .tab:hover:not([data-active]) .count {
      color: var(--ui-muted);
    }
  }

  @media (pointer: coarse) {
    .tab::after {
      content: "";
      position: absolute;
      inset: -4px 0;
    }
  }

  /* ---------- Vertical ---------- */

  /* The 480px container breakpoint below must match the script, which reads
     the axis from the layout. */
  .tabs[data-layout="vertical"] {
    container-type: inline-size;
    grid-template-columns: auto minmax(0, 1fr);
    column-gap: var(--ui-space-6);
    align-items: start;
  }

  .tabs[data-layout="vertical"] > * {
    grid-column: 1 / -1;
  }

  @container (width >= 480px) {
    .tabs[data-layout="vertical"] > * {
      grid-column: auto;
    }

    .tabs[data-layout="vertical"] > .list {
      flex-direction: column;
      justify-self: stretch;
      min-width: 160px;
      padding: 0;
      border-radius: 0;
      box-shadow: none;
      overflow: visible;
      mask-image: none;
    }

    .tabs[data-layout="vertical"] > .list > .indicator {
      top: 0;
      width: 100%;
      height: var(--active-tab-height);
      transform: translateY(var(--active-tab-top));
    }

    .tabs[data-layout="vertical"] > .list > .tab {
      justify-content: flex-start;
    }

    .tabs[data-layout="vertical"] > .list > .tab > .count {
      margin-inline-start: auto;
      padding-inline-start: var(--ui-space-3);
    }

    /* Rows touch, so the hit area can't extend past them; the row grows instead. */
    @media (pointer: coarse) {
      .tabs[data-layout="vertical"] > .list > .tab {
        height: 40px;
      }
      .tabs[data-layout="vertical"] > .list > .tab::after {
        inset: 0;
      }
    }
  }

  .panel {
    min-width: 0;
    border-radius: var(--ui-radius-md);
  }

  .panel:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .panels {
    display: grid;
  }

  .panel[data-crossfade] {
    grid-area: 1 / 1;
    /* Base UI marks unselected panels hidden; here they still hold the cell. */
    display: block;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .panel[data-crossfade][data-selected] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @media (prefers-reduced-motion: reduce) {
    .panel[data-crossfade],
    .panel[data-crossfade][data-selected] {
      transition: none;
    }
  }
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import { DirectionProvider } from "@base-ui/react/direction-provider";
import { TextMorph } from "../text-morph/text-morph";
import { flyPill, stopPill } from "./pill-flight";
import styles from "./tabs.module.css";

type Orientation = "horizontal" | "vertical";

type TabsContextValue = {
  value: string;
  crossfade: boolean;
  manual: boolean;
  setAxis: (axis: Orientation) => void;
  register: (value: string) => () => void;
};

const TabsContext = createContext<TabsContextValue | null>(null);

function useTabs(part: string) {
  const context = useContext(TabsContext);
  if (!context) throw new Error(`<${part}> must be inside <Tabs>.`);
  return context;
}

type TabsProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange"> & {
  /** Controlled value. Pair with `onValueChange`. */
  value?: string;
  /** Uncontrolled starting value, used when the URL has no valid `param`. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Arrow keys move focus only; Enter or Space selects. Use when showing a panel is slow. */
  manual?: boolean;
  /** Stack panels in one cell and crossfade between them. */
  crossfade?: boolean;
  /** Keep the selected tab in this search param (`?tab=notes`). Uncontrolled only. */
  param?: string;
  /** `vertical` puts the tabs in a column beside the panels; under 480px wide it falls back to a row. */
  orientation?: Orientation;
};

export function Tabs({
  value: controlledValue,
  defaultValue,
  onValueChange,
  manual = false,
  crossfade = false,
  param,
  orientation = "horizontal",
  className,
  children,
  ...props
}: TabsProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? "");
  const value = controlledValue ?? uncontrolledValue;
  const controlled = controlledValue !== undefined;
  // The axis the list is laid out on now. A vertical list falls back to a row
  // under 480px, and Base UI's arrow keys follow what's on screen.
  const [axis, setAxis] = useState<Orientation>(orientation);

  // Tabs register their values so a URL can't select a tab that doesn't exist.
  const values = useRef(new Set<string>());
  const register = useCallback((v: string) => {
    values.current.add(v);
    return () => {
      values.current.delete(v);
    };
  }, []);

  const select = useCallback(
    (next: string) => {
      if (!controlled) setUncontrolledValue(next);
      onValueChange?.(next);
      if (param && !controlled) {
        const url = new URL(window.location.href);
        url.searchParams.set(param, next);
        window.history.replaceState(window.history.state, "", url);
      }
    },
    [controlled, onValueChange, param],
  );

  // A layout effect, so children's have run and every tab is registered.
  useLayoutEffect(() => {
    if (!param || controlled) return;
    function sync() {
      const fromUrl = new URLSearchParams(window.location.search).get(param!);
      setUncontrolledValue(fromUrl && values.current.has(fromUrl) ? fromUrl : (defaultValue ?? ""));
    }
    sync();
    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, [param, controlled, defaultValue]);

  return (
    <TabsContext value={{ value, crossfade, manual, setAxis, register }}>
      <BaseTabs.Root
        // Always controlled: the URL and `param` live here, not in Base UI.
        value={value === "" ? null : value}
        onValueChange={(next, details) => {
          // Only user picks; ignore Base UI's own fallbacks for missing tabs.
          if (details.reason !== "none" || typeof next !== "string") return;
          select(next);
        }}
        orientation={axis}
        className={className ? `${styles.tabs} ${className}` : styles.tabs}
        data-layout={orientation}
        {...props}
      >
        {children}
      </BaseTabs.Root>
    </TabsContext>
  );
}

type TabListProps = Omit<ComponentProps<"div">, "role"> & {
  /** Names the set of tabs for screen readers, e.g. "Estimate sections". */
  "aria-label"?: string;
  "aria-labelledby"?: string;
};

/** The axis the list is laid out on now: read, not assumed, since the CSS can fall back to a row. */
function axisOf(list: HTMLElement): Orientation {
  return getComputedStyle(list).flexDirection.startsWith("column") ? "vertical" : "horizontal";
}

/** A tab's offset and length along the list, measured the way Base UI places the indicator. */
function span(tab: HTMLElement, list: HTMLElement, vertical: boolean) {
  const t = tab.getBoundingClientRect();
  const l = list.getBoundingClientRect();
  return vertical
    ? { start: t.top - l.top + list.scrollTop - list.clientTop, length: t.height }
    : { start: t.left - l.left + list.scrollLeft - list.clientLeft, length: t.width };
}

export function TabList({ className, children, ...props }: TabListProps) {
  const { value, manual, setAxis } = useTabs("TabList");
  const listRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);
  const [direction, setDirection] = useState<"ltr" | "rtl">("ltr");
  const previous = useRef<string | null>(null);
  // Nothing animates until the first paint, so a tab picked from the URL is simply there.
  const painted = useRef(false);
  useEffect(() => {
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        painted.current = true;
      });
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  // Base UI's Indicator rests the pill on the selected tab through its CSS
  // variables. On a change of tab, this plays the flight between them on top.
  useLayoutEffect(() => {
    const list = listRef.current;
    const indicator = indicatorRef.current;
    const from = previous.current;
    previous.current = value;
    if (!list || !indicator || from === null || from === value) return;
    const tab = list.querySelector<HTMLElement>('[role="tab"][data-active]');
    const last = Array.from(list.querySelectorAll<HTMLElement>('[role="tab"]')).find((t) => t.dataset.value === from);
    if (!tab || !last) return;

    const vertical = axisOf(list) === "vertical";
    // A change mid-move starts from where the pill is on screen.
    const origin = stopPill(indicator, vertical) ?? span(last, list, vertical);
    if (!painted.current) return;
    flyPill(indicator, origin, span(tab, list, vertical), vertical);
  }, [value]);

  useLayoutEffect(() => {
    const list = listRef.current;
    if (!list) return;
    setAxis(axisOf(list));
    setDirection(getComputedStyle(list).direction === "rtl" ? "rtl" : "ltr");
  }, [setAxis]);

  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    let frame = 0;
    const edges = () => {
      const max = list.scrollWidth - list.clientWidth;
      const start = Math.abs(list.scrollLeft);
      list.toggleAttribute("data-overflow-start", start > 1);
      list.toggleAttribute("data-overflow-end", max - start > 1);
    };
    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => setAxis(axisOf(list)));
      edges();
    });
    observer.observe(list);
    // The scrollbar is hidden, so a vertical wheel scrolls the tabs; at either
    // end it goes back to scrolling the page.
    const wheel = (event: WheelEvent) => {
      if (event.ctrlKey || event.shiftKey || Math.abs(event.deltaX) >= Math.abs(event.deltaY)) return;
      const max = list.scrollWidth - list.clientWidth;
      if (max <= 1) return;
      const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? list.clientWidth : 1;
      const rtl = getComputedStyle(list).direction === "rtl";
      const by = event.deltaY * unit * (rtl ? -1 : 1);
      const start = Math.abs(list.scrollLeft);
      if ((by > 0) !== rtl ? max - start <= 1 : start <= 1) return;
      event.preventDefault();
      list.scrollBy({ left: by });
    };
    list.addEventListener("scroll", edges, { passive: true });
    list.addEventListener("wheel", wheel, { passive: false });
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      list.removeEventListener("scroll", edges);
      list.removeEventListener("wheel", wheel);
    };
  }, [setAxis]);

  return (
    <DirectionProvider direction={direction}>
      <BaseTabs.List
        ref={listRef}
        activateOnFocus={!manual}
        className={className ? `${styles.list} ${className}` : styles.list}
        {...props}
      >
        <BaseTabs.Indicator ref={indicatorRef} className={styles.indicator} aria-hidden="true" />
        {children}
      </BaseTabs.List>
    </DirectionProvider>
  );
}

type TabProps = Omit<ComponentProps<"button">, "value" | "role"> & {
  value: string;
  children: ReactNode;
  /** A count after the label, read as part of the tab's name ("Guests, 14"). */
  count?: number | string;
};

export function Tab({ value, count, className, children, onFocus, ...props }: TabProps) {
  const { register } = useTabs("Tab");

  useLayoutEffect(() => register(value), [register, value]);

  return (
    <BaseTabs.Tab
      value={value}
      data-value={value}
      className={className ? `${styles.tab} ${className}` : styles.tab}
      onFocus={(event) => {
        onFocus?.(event);
        // Arrowing to a tab hidden past the fade scrolls it into view.
        if (event.currentTarget.matches(":focus-visible")) {
          event.currentTarget.scrollIntoView({ block: "nearest", inline: "nearest" });
        }
      }}
      {...props}
    >
      {count === undefined || count === "" ? (
        children
      ) : (
        <>
          <span className={styles.label}>
            {children}
            {/* Screen-reader-only pause, so the name reads "Guests, 14". */}
            <span className={styles.pause}>,</span>
          </span>
          <span className={styles.count}>
            <TextMorph>{String(count)}</TextMorph>
          </span>
        </>
      )}
    </BaseTabs.Tab>
  );
}

type TabPanelProps = Omit<ComponentProps<"div">, "role"> & {
  value: string;
};

export function TabPanel({ value, className, children, ...props }: TabPanelProps) {
  const { value: selected, crossfade } = useTabs("TabPanel");
  return (
    <BaseTabs.Panel
      value={value}
      // Unselected panels stay mounted, so their state survives a switch.
      keepMounted
      data-crossfade={crossfade || undefined}
      data-selected={value === selected || undefined}
      className={className ? `${styles.panel} ${className}` : styles.panel}
      {...props}
    >
      {children}
    </BaseTabs.Panel>
  );
}

/** Wraps the panels when `crossfade` is on, so they share one grid cell. */
export function TabPanels({ className, ...props }: ComponentProps<"div">) {
  return <div className={className ? `${styles.panels} ${className}` : styles.panels} {...props} />;
}

@layer theme, base, components, utilities;

.content {
  composes: wrap from "../text/text.module.css";
}

@layer components {
  /* The whole control, track included, is a control height: --segmented-h.
     The options sit inside it, --segmented-pad from every edge. Track, pill
     and inset are the Tabs' own (--ui-track-* in the tokens): the two share
     one look and differ only in what they mean. */
  .root {
    --segmented-h: var(--ui-control-md);
    --segmented-pad: var(--ui-track-inset);
    --segmented-option: calc(var(--segmented-h) - var(--segmented-pad) * 2);
    position: relative;
    isolation: isolate;
    display: inline-grid;
    grid-auto-flow: column;
    grid-auto-columns: minmax(max-content, 1fr);
    max-width: 100%;
    /* Labels stay whole, so in a container too narrow for them the options
       scroll sideways inside the track instead of pushing the page. */
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
    padding: var(--segmented-pad);
    border-radius: var(--ui-radius-full);
    box-shadow: var(--ui-track-edge);
    font-family: var(--ui-font-sans);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  /* Tabs come in one size. At sm a 4px inset would leave a 24px pill too
     tight around its label, so the inset drops by 1px; all else is shared. */
  .root[data-size="sm"] {
    --segmented-h: var(--ui-control-sm);
    --segmented-pad: calc(var(--ui-track-inset) - 1px);
  }

  .root[data-size="sm"] .option {
    padding-inline: 12px;
    font-size: var(--ui-text-sm);
  }

  .root[data-widths="content"] {
    grid-auto-columns: auto;
  }

  .indicator {
    position: absolute;
    top: var(--segmented-pad);
    left: 0;
    z-index: -1;
    height: var(--segmented-option);
    border-radius: var(--ui-radius-full);
    background: var(--ui-track-pill);
    contain: strict;
    pointer-events: none;
    visibility: hidden;
  }

  .root[data-ready] .indicator[data-visible] {
    visibility: visible;
  }

  .option {
    position: relative;
    display: grid;
    place-items: center;
    min-width: 0;
    height: var(--segmented-option);
    padding-inline: 14px;
    border-radius: var(--ui-radius-full);
    color: var(--ui-muted);
    /* One weight in every state, so selecting never changes a width. */
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .option[data-checked] {
    color: var(--ui-foreground);
  }

  /* Until the pill has measured, the checked option carries it itself. */
  .root:not([data-ready]) .option[data-checked] {
    background: var(--ui-track-pill);
  }

  @media (hover: hover) {
    .option:hover:not([data-checked], [data-disabled]) {
      color: var(--ui-foreground);
    }
  }

  .option:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .content {
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-2);
    /* A label with a count beside it stays on one line, like any other. */
    white-space: nowrap;
    pointer-events: none;
  }

  .content svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
  }

  .option[data-disabled] {
    opacity: 0.5;
    cursor: default;
  }

  @media (pointer: coarse) {
    .option::after {
      content: "";
      position: absolute;
      inset: -4px 0;
    }
  }
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { flyPill, stopPill } from "../tabs/pill-flight";
import styles from "./segmented-control.module.css";

type SegmentedControlProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "role"> & {
  /** Accessible name of the group. */
  "aria-label"?: string;
  "aria-labelledby"?: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** `equal`: every option as wide as the widest. `content`: each as wide as its label. */
  widths?: "equal" | "content";
  /** Form field name. */
  name?: string;
  disabled?: boolean;
  /** Outer height, track included: `sm` matches a small button or select, `md` a default one. */
  size?: "sm" | "md";
};

/** A Base UI radio group with one pill that glides to the checked option, as the Tabs pill does. */
export function SegmentedControl({
  value: controlledValue,
  defaultValue,
  onValueChange,
  widths = "equal",
  size = "md",
  name,
  disabled = false,
  className,
  children,
  ...props
}: SegmentedControlProps) {
  const [uncontrolledValue, setUncontrolledValue] = useState(defaultValue ?? "");
  const value = controlledValue ?? uncontrolledValue;

  const select = useCallback(
    (next: string) => {
      if (controlledValue === undefined) setUncontrolledValue(next);
      onValueChange?.(next);
    },
    [controlledValue, onValueChange],
  );

  const rootRef = useRef<HTMLDivElement>(null);
  const indicatorRef = useRef<HTMLSpanElement>(null);
  const placed = useRef<{ value: string; x: number; width: number } | null>(null);
  const painted = useRef(false);
  useEffect(() => {
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        painted.current = true;
      });
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  const place = useCallback(
    (animate: boolean) => {
      const root = rootRef.current;
      const indicator = indicatorRef.current;
      const option = root?.querySelector<HTMLElement>(`[data-value="${CSS.escape(value)}"]`);
      if (!root || !indicator) return;
      if (!option) {
        indicator.removeAttribute("data-visible");
        placed.current = null;
        return;
      }

      // Not offsetLeft: it rounds, and equal-width options rarely land on whole pixels.
      const box = option.getBoundingClientRect();
      // Plus the scroll, for a control that scrolls sideways in a narrow container.
      const x = box.left - root.getBoundingClientRect().left + root.scrollLeft;
      const width = box.width;
      const last = placed.current;
      indicator.setAttribute("data-visible", "");
      if (last && last.value === value && last.x === x && last.width === width) return;

      // A change mid-move starts from where the pill is on screen.
      const origin = stopPill(indicator) ?? (last ? { start: last.x, length: last.width } : null);
      indicator.style.transform = `translateX(${x}px)`;
      indicator.style.width = `${width}px`;
      placed.current = { value, x, width };

      const moved = last && last.value !== value;
      if (!animate || !moved || !origin || !painted.current) return;
      // The same flight as the Tabs pill: stretch, dip and draw in.
      flyPill(indicator, origin, { start: x, length: width });
    },
    [value],
  );

  useLayoutEffect(() => {
    place(true);
    rootRef.current?.setAttribute("data-ready", "");
  }, [place]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    let frame = 0;
    const remeasure = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => place(false));
    };
    const observer = new ResizeObserver(remeasure);
    observer.observe(root);
    for (const option of root.querySelectorAll("[data-value]")) observer.observe(option);
    document.fonts?.ready.then(remeasure);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [place]);

  return (
    <BaseRadioGroup
      ref={rootRef}
      value={value}
      onValueChange={(next) => select(next as string)}
      name={name}
      disabled={disabled}
      data-widths={widths}
      data-size={size}
      className={className ? `${styles.root} ${className}` : styles.root}
      {...props}
    >
      <span ref={indicatorRef} className={styles.indicator} aria-hidden="true" />
      {children}
    </BaseRadioGroup>
  );
}

type SegmentProps = Omit<ComponentProps<"span">, "children" | "role"> & {
  value: string;
  children: ReactNode;
  disabled?: boolean;
};

/** One option. For an icon-only option, pass `aria-label`. */
export function Segment({ value, children, disabled, className, ...props }: SegmentProps) {
  return (
    <BaseRadio.Root
      value={value}
      disabled={disabled}
      data-value={value}
      className={className ? `${styles.option} ${className}` : styles.option}
      {...props}
    >
      <span className={styles.content}>{children}</span>
    </BaseRadio.Root>
  );
}

@layer theme, base, components, utilities;

@layer components {
  /* Base UI's Positioner places this element; the panel inside it animates. */
  .positioner {
    z-index: 50;
    max-width: min(360px, calc(100vw - 16px));
    outline: none;
  }

  .panel {
    --popover-pad: var(--ui-space-4);
    position: relative;
    box-sizing: border-box;
    padding: var(--popover-pad);
    border-radius: calc(var(--popover-pad) + var(--ui-control-sm) / 2);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-floating);
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    text-wrap: pretty;
    outline: none;
    transform-origin: var(--transform-origin);
    opacity: 1;
    scale: 1;
    filter: none;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter),
      scale var(--ui-dur-fast) var(--ui-ease-enter),
      filter var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .panel[data-starting-style],
  .panel[data-ending-style] {
    opacity: 0;
    scale: 0.97;
    filter: blur(2px);
  }

  .panel[data-ending-style] {
    transition-duration: var(--ui-dur-instant);
    transition-timing-function: var(--ui-ease-exit);
  }

  /* Base UI sets the arrow's offset along the edge; the SVG points down by default. */
  .arrow {
    position: absolute;
    width: 16px;
    height: 8px;
  }

  .arrow svg {
    display: block;
    width: 16px;
    height: 8px;
    overflow: visible;
  }

  .arrowFill {
    fill: var(--ui-surface);
  }

  .arrowEdge {
    fill: none;
    stroke: var(--ui-border);
    stroke-width: var(--ui-hairline);
    vector-effect: non-scaling-stroke;
  }

  .arrow[data-side="top"] {
    top: 100%;
  }

  .arrow[data-side="bottom"] {
    bottom: 100%;
    rotate: 180deg;
  }

  .arrow[data-side="left"] {
    left: calc(100% - 4px);
    rotate: -90deg;
  }

  .arrow[data-side="right"] {
    right: calc(100% - 4px);
    rotate: 90deg;
  }

  @media (prefers-reduced-motion: reduce) {
    .panel {
      transition: none;
    }
    .panel[data-starting-style],
    .panel[data-ending-style] {
      scale: none;
    }
  }
}

"use client";

import {
  useCallback,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { Popover as BasePopover } from "@base-ui/react/popover";
import styles from "./popover.module.css";

export type Side = "top" | "bottom" | "left" | "right";
export type Align = "start" | "center" | "end";

type PopoverProps = {
  /** A button; it gets aria-expanded and aria-controls. */
  trigger: ReactElement;
  /** Content, or a function that receives `close`. */
  children: ReactNode | ((api: { close: () => void }) => ReactNode);
  /** `content` focuses inside as a dialog (forms); `none` keeps focus on the trigger. */
  focus?: "content" | "none";
  /** Required when `focus="content"` unless `labelledBy` is set. */
  label?: string;
  labelledBy?: string;
  side?: Side;
  align?: Align;
  arrow?: boolean;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
};

/** Portal into the nearest themed subtree (tokens) or open modal dialog (else it's inert). */
function portalTarget(trigger: HTMLElement | null) {
  return trigger?.closest<HTMLElement>("dialog[open], [data-theme]") ?? undefined;
}

export function Popover({
  trigger,
  children,
  focus = "content",
  label,
  labelledBy,
  side = "bottom",
  align = "center",
  arrow = false,
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  className,
}: PopoverProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const open = controlledOpen ?? uncontrolledOpen;
  const [triggerEl, setTriggerEl] = useState<HTMLElement | null>(null);
  const popupRef = useRef<HTMLDivElement>(null);

  const setOpen = useCallback(
    (next: boolean) => {
      if (controlledOpen === undefined) setUncontrolledOpen(next);
      onOpenChange?.(next);
    },
    [controlledOpen, onOpenChange],
  );
  const close = useCallback(() => setOpen(false), [setOpen]);

  const isDialog = focus === "content";

  return (
    <BasePopover.Root open={open} onOpenChange={(next) => setOpen(next)}>
      <BasePopover.Trigger
        ref={setTriggerEl}
        render={trigger}
        aria-haspopup={isDialog ? "dialog" : undefined}
      />
      <BasePopover.Portal container={portalTarget(triggerEl)}>
        <BasePopover.Positioner
          className={styles.positioner}
          side={side}
          align={align}
          sideOffset={arrow ? 12 : 8}
          collisionPadding={8}
        >
          <BasePopover.Popup
            ref={popupRef}
            className={className ? `${styles.panel} ${className}` : styles.panel}
            role={isDialog ? "dialog" : undefined}
            aria-label={labelledBy ? undefined : label}
            aria-labelledby={labelledBy}
            initialFocus={
              isDialog
                ? () => popupRef.current?.querySelector<HTMLElement>("[autofocus]") ?? true
                : false
            }
          >
            {typeof children === "function" ? children({ close }) : children}
            {arrow && (
              <BasePopover.Arrow className={styles.arrow}>
                <svg viewBox="0 0 16 8" aria-hidden="true">
                  <path className={styles.arrowFill} d="M0 0h16L9.41 6.59a2 2 0 0 1-2.82 0z" />
                  <path className={styles.arrowEdge} d="M0 0l6.59 6.59a2 2 0 0 0 2.82 0L16 0" />
                </svg>
              </BasePopover.Arrow>
            )}
          </BasePopover.Popup>
        </BasePopover.Positioner>
      </BasePopover.Portal>
    </BasePopover.Root>
  );
}

@layer theme, base, components, utilities;

.name {
  composes: wrap from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  /* ---------- Trigger ---------- */

  .root {
    display: inline-flex;
    flex-shrink: 0;
  }

  .trigger {
    --usage-arc: var(--ui-foreground);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);

    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: var(--ui-control-sm);
    padding: 0 12px 0 10px;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: none;
    color: var(--ui-muted);
    isolation: isolate;
    font: var(--ui-weight-medium) var(--ui-text-sm) / 1 var(--ui-font-sans);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .trigger[data-tone="warning"] {
    --usage-arc: var(--ui-warning);
    color: var(--ui-warning-text);
  }

  .trigger[data-tone="danger"] {
    --usage-arc: var(--ui-danger);
    color: var(--ui-danger-text);
  }

  /* No press scale: the popover is anchored to the trigger's real box. */
  .trigger::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: transparent;
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .trigger[data-tone="calm"]:hover {
      color: var(--ui-foreground);
    }
    .trigger:hover::before {
      background: var(--ui-fill);
    }
  }

  .trigger[aria-expanded="true"]::before {
    background: var(--ui-fill);
  }

  .trigger[data-tone="calm"][aria-expanded="true"] {
    color: var(--ui-foreground);
  }

  .trigger:active::before {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  .trigger:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  @media (pointer: coarse) {
    .trigger::after {
      content: "";
      position: absolute;
      inset: -4px;
    }
  }

  /* Starts at twelve o'clock and fills clockwise. */
  .ring {
    flex-shrink: 0;
    width: 16px;
    height: 16px;
    rotate: -90deg;
    overflow: visible;
  }

  :is([dir="rtl"]) .ring {
    scale: 1 -1;
  }

  .ringTrack,
  .ringArc {
    fill: none;
    stroke-width: 2;
  }

  .ringTrack {
    stroke: var(--ui-fill-strong);
  }

  .ringArc {
    stroke: var(--usage-arc);
    stroke-linecap: round;
    stroke-dasharray: 100 200;
    transition:
      stroke-dashoffset var(--ui-dur-move) var(--ui-ease-move),
      stroke var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* A round cap draws a dot at zero length. */
  .ringArc[data-empty] {
    opacity: 0;
  }

  /* Translated, not scaled, so the leading end keeps its round cap. */
  .miniBar {
    position: relative;
    flex-shrink: 0;
    width: 20px;
    height: 4px;
    overflow: hidden;
    border-radius: var(--ui-radius-full);
    background: var(--ui-fill-strong);
  }

  .miniBar::before {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: var(--usage-arc);
    translate: calc((var(--usage) - 1) * 100%) 0;
    transition:
      translate var(--ui-dur-move) var(--ui-ease-move),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  :is([dir="rtl"]) .miniBar::before {
    translate: calc((1 - var(--usage)) * 100%) 0;
  }

  /* ---------- Reserved width ---------- */

  /* The widest text sits hidden in the same cell, so a changing figure never moves what's beside it. */
  .reserve {
    display: inline-grid;
    justify-items: end;
    font-variant-numeric: tabular-nums;
  }

  .sizer,
  .reserved {
    grid-area: 1 / 1;
  }

  .sizer {
    visibility: hidden;
  }

  .triggerPercent {
    justify-items: start;
  }

  /* ---------- Breakdown ---------- */

  .panel {
    width: min(320px, calc(100vw - 16px));
  }

  /* Three categorical hues, mixed from the accent, success and danger tokens so each theme
     gets its own tuned steps. Checked as a set in both themes: every pair stays apart under
     protan and deutan simulation, and each holds 3:1 on the surface. Orchid, teal, blue
     (the last, usually the largest, is the calmest):
     none of them is the amber or red the tones use. Without segments the one fill is the blue. Segments
     past the third, and "Other", are a neutral gray; free space is the unfilled track. */
  .breakdown {
    --usage-1: color-mix(in oklch, color-mix(in oklch, var(--ui-accent) 45%, var(--ui-danger)) 90%, var(--ui-surface));
    --usage-2: color-mix(in oklch, color-mix(in oklch, var(--ui-accent) 20%, var(--ui-success)) 90%, var(--ui-surface));
    --usage-3: var(--ui-accent);
    --usage-other: color-mix(in oklch, var(--ui-foreground) 42%, var(--ui-surface));
    --usage-free: var(--ui-fill-strong);
    --usage-free-edge: var(--ui-border-strong);
    --usage-percent: var(--ui-muted);
    --usage-icon: var(--ui-subtle);
    --usage-message: var(--ui-muted);
    display: grid;
    gap: var(--ui-space-4);
    min-width: 0;
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
  }

  /* A tone tints what's left, never the segments: the hues keep meaning "what", the tint says "how much room". */
  .breakdown[data-tone="warning"] {
    --usage-free: color-mix(in oklch, var(--ui-warning) 22%, transparent);
    --usage-free-edge: var(--ui-border-warning);
    --usage-percent: var(--ui-warning-text);
    --usage-icon: var(--ui-warning);
    --usage-message: var(--ui-warning-text);
  }

  .breakdown[data-tone="danger"] {
    --usage-free: color-mix(in oklch, var(--ui-danger) 20%, transparent);
    --usage-free-edge: var(--ui-border-danger);
    --usage-percent: var(--ui-danger-text);
    --usage-icon: var(--ui-danger);
    --usage-message: var(--ui-danger-text);
  }

  .head {
    display: grid;
    gap: var(--ui-space-1);
  }

  .title {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-sm);
  }

  .figure {
    margin: 0;
  }

  .figureLine {
    display: flex;
    align-items: baseline;
    gap: var(--ui-space-2);
    min-width: 0;
  }

  .used {
    font-variant-numeric: tabular-nums;
    font-size: var(--ui-text-2xl);
    font-weight: var(--ui-weight-semibold);
    line-height: var(--ui-leading-2xl);
    white-space: nowrap;
  }

  .of {
    flex: 1;
    min-width: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    font-variant-numeric: tabular-nums;
  }

  .percent {
    color: var(--usage-percent);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* Each segment is a full-width layer clipped to its span, so a change slides its edges
     instead of resizing anything. Every segment ends 2px short, and the free track starts
     2px after the last one, so the gaps show the surface and neighbors never bleed. */
  .bar {
    position: relative;
    height: 8px;
    overflow: hidden;
    border-radius: var(--ui-radius-full);
  }

  /* From the danger tone the bar gets an edge, a hairline off it, so it still says "nearly out" once
     the colored segments have filled the track. */
  .breakdown[data-tone="danger"] .bar {
    outline: var(--ui-hairline) solid var(--usage-free-edge);
    outline-offset: 2px;
  }

  .bar::before {
    content: "";
    position: absolute;
    inset: 0;
    background: var(--usage-free);
    /* min(used × 1000, 1) is 0 when nothing is used, so an empty bar has no gap at its start. */
    clip-path: inset(0 0 0 calc(var(--used) * 100% + min(var(--used) * 1000, 1) * 2px));
    transition:
      clip-path var(--ui-dur-move) var(--ui-ease-move),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  :is([dir="rtl"]) .bar::before {
    clip-path: inset(0 calc(var(--used) * 100% + min(var(--used) * 1000, 1) * 2px) 0 0);
  }

  .segment {
    position: absolute;
    inset: 0;
    background: var(--usage-other);
    clip-path: inset(0 calc((1 - var(--end)) * 100% + 2px) 0 calc(var(--start) * 100%));
    transition:
      clip-path var(--ui-dur-move) var(--ui-ease-move),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* The last segment runs to the end when the bar is full. */
  .segment[data-last][data-full] {
    clip-path: inset(0 0 0 calc(var(--start) * 100%));
  }

  :is([dir="rtl"]) .segment {
    clip-path: inset(0 calc(var(--start) * 100%) 0 calc((1 - var(--end)) * 100% + 2px));
  }

  :is([dir="rtl"]) .segment[data-last][data-full] {
    clip-path: inset(0 calc(var(--start) * 100%) 0 0);
  }

  .segment[data-index="0"],
  .swatch[data-index="0"] {
    background: var(--usage-1);
  }

  .segment[data-index="1"],
  .swatch[data-index="1"] {
    background: var(--usage-2);
  }

  .segment[data-index="2"],
  .swatch[data-index="2"],
  .segment[data-index="used"] {
    background: var(--usage-3);
  }

  .legend {
    display: grid;
    gap: var(--ui-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .item {
    display: grid;
    grid-template-columns: 8px minmax(0, 1fr) auto;
    align-items: center;
    column-gap: var(--ui-space-2);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
  }

  .swatch {
    width: 8px;
    height: 8px;
    border-radius: var(--ui-radius-full);
    background: var(--usage-other);
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .swatch[data-free] {
    background: var(--usage-free);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--usage-free-edge);
  }

  .item[data-free] .name {
    color: var(--ui-muted);
  }

  .amount {
    color: var(--ui-muted);
    font-variant-numeric: tabular-nums;
    text-align: end;
    white-space: nowrap;
  }

  /* ---------- What happens next ---------- */

  .status {
    display: grid;
    gap: var(--ui-space-3);
    padding-top: var(--ui-space-4);
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  .message,
  .result {
    display: grid;
    grid-template-columns: 16px minmax(0, 1fr);
    gap: var(--ui-space-2);
    align-items: start;
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .message {
    color: var(--usage-message);
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .message > svg,
  .result > svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    margin-top: calc((var(--ui-leading-md) - 16px) / 2);
  }

  .message > svg {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    color: var(--usage-icon);
  }

  .result {
    color: var(--ui-foreground);
  }

  .result:focus {
    outline: none;
  }

  .result > svg {
    color: var(--ui-success);
  }

  .figures {
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .countBox {
    justify-items: start;
  }

  .count {
    font-weight: var(--ui-weight-medium);
  }

  .message[data-enter],
  .result[data-enter] {
    animation: usage-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes usage-in {
    from {
      opacity: 0;
    }
  }

  .error {
    margin: 0;
    color: var(--ui-danger-text);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .action {
    justify-self: start;
  }

  @media (prefers-reduced-motion: reduce) {
    .ringArc,
    .miniBar::before,
    .bar::before,
    .segment {
      transition-property: stroke, opacity, background-color;
    }
    .message[data-enter],
    .result[data-enter] {
      animation: none;
    }
  }
}

"use client";

import { useEffect, useId, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import type { Align, Side } from "../popover/popover";
import { AnimatedSize } from "../animated-size/animated-size";
import { Button } from "../button/button";
import { Icon, type IconName } from "../icons/icons";
import { Popover } from "../popover/popover";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./usage-meter.module.css";

export type UsageKind = "tokens" | "money";
export type UsageTone = "calm" | "warning" | "danger";

export type UsageSegment = {
  id: string;
  /** What the usage is: "Files", "Conversation". */
  label: string;
  /** In the same unit as `used`. */
  value: number;
};

export type UsageThresholds = {
  /** Fraction of `limit` where the warning starts. Default 0.75. */
  warning: number;
  /** Fraction of `limit` where the danger tone starts. Default 0.95. */
  danger: number;
};

/** Controlled. Leave it undefined while nothing has been compacted. */
export type UsageCompaction =
  | { status: "running" }
  | { status: "done"; before: number; after: number }
  | { status: "failed"; error?: string };

export type UsageProps = {
  used: number;
  limit: number;
  /** `tokens` formats as 124k and 1.2M; `money` formats with `currency`. */
  kind?: UsageKind;
  /** What the usage is made of. Anything `used` has beyond their sum shows as "Other". */
  segments?: UsageSegment[];
  thresholds?: Partial<UsageThresholds>;
  /** Names the meter. Defaults to "Context window", or "Budget" for money. */
  label?: string;
  /** Who uses it, for the default messages: "Copper". */
  agent?: string;
  /** Said after the limit for money: "today", "this month". */
  period?: string;
  /** ISO 4217 code for money. Default "USD". */
  currency?: string;
  /** Fixed so server and browser format numbers alike. */
  locale?: string;
  /** Replaces the built-in number formatting. */
  format?: (value: number) => string;
  /** One line per tone, replacing the defaults. */
  messages?: Partial<Record<UsageTone, string>>;
  /** Shows an action from the warning tone up. */
  onCompact?: () => void;
  compactLabel?: string;
  compaction?: UsageCompaction;
};

type UsageMeterProps = UsageProps & {
  /** The small mark beside the percentage. */
  indicator?: "ring" | "bar";
  side?: Side;
  align?: Align;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
};

type UsageBreakdownProps = UsageProps & {
  className?: string;
  /** Off inside UsageMeter, which announces from outside the popover. */
  announce?: boolean;
  /** Set by UsageMeter so the popover is named by the title and figure. */
  titleId?: string;
  figureId?: string;
};

const DEFAULT_THRESHOLDS: UsageThresholds = { warning: 0.75, danger: 0.95 };
const RANK: Record<UsageTone, number> = { calm: 0, warning: 1, danger: 2 };
const TONE_ICON: Record<UsageTone, IconName> = { calm: "info", warning: "warning", danger: "alert" };
const OTHER = "\u0000other";

function tokens(value: number, locale: string) {
  const number = (v: number, digits: number) => new Intl.NumberFormat(locale, { maximumFractionDigits: digits }).format(v);
  const size = Math.abs(value);
  if (size < 1000) return number(value, 0);
  // Rounded first, so 999,600 reads "1M", not "1,000k".
  let scaled = value / 1000;
  let suffix = "k";
  if (Math.round(Math.abs(scaled)) >= 1000) {
    scaled = value / 1_000_000;
    suffix = "M";
  }
  return number(scaled, Math.abs(scaled) < 10 ? 1 : 0) + suffix;
}

function useFormat(kind: UsageKind, locale: string, currency: string, format?: (value: number) => string) {
  const money = useMemo(() => new Intl.NumberFormat(locale, { style: "currency", currency }), [locale, currency]);
  const exact = useMemo(() => new Intl.NumberFormat(locale), [locale]);
  return {
    short: format ?? ((v: number) => (kind === "money" ? money.format(v) : tokens(v, locale))),
    /** For screen readers: 124,000, not 124k. */
    full: kind === "money" ? (v: number) => money.format(v) : (v: number) => exact.format(Math.round(v)),
  };
}

function read({ used, limit, thresholds }: Pick<UsageProps, "used" | "limit" | "thresholds">) {
  const safeUsed = Number.isFinite(used) ? Math.max(used, 0) : 0;
  const safeLimit = Number.isFinite(limit) && limit > 0 ? limit : 0;
  const fraction = safeLimit ? safeUsed / safeLimit : 0;
  const warning = thresholds?.warning ?? DEFAULT_THRESHOLDS.warning;
  const danger = Math.max(thresholds?.danger ?? DEFAULT_THRESHOLDS.danger, warning);
  const tone: UsageTone = fraction >= danger ? "danger" : fraction >= warning ? "warning" : "calm";
  // Floored, so it never says 100% before it is; any use at all shows at least 1%.
  const percent = safeUsed <= 0 ? 0 : fraction >= 1 ? 100 : Math.min(99, Math.max(1, Math.floor(fraction * 100)));
  return { used: safeUsed, limit: safeLimit, fraction: Math.min(fraction, 1), full: fraction >= 1, tone, percent };
}

function defaultMessage(tone: UsageTone, full: boolean, kind: UsageKind, agent: string, limitText: string, leftText: string, period?: string) {
  if (kind === "money") {
    if (tone === "calm") return `${leftText} left${period ? ` ${period}` : ""}.`;
    if (full) return `Budget reached. ${agent} is paused until it resets or you raise it.`;
    return `${tone === "danger" ? "Only " : ""}${leftText} left. ${agent} pauses when it reaches ${limitText}.`;
  }
  if (tone === "calm") return `${agent} can see the whole conversation.`;
  if (full) return `Full. ${agent} is forgetting the oldest messages.`;
  return `${tone === "danger" ? "Nearly full. " : ""}${agent} will start forgetting the oldest messages at ${limitText}.`;
}

function useUsage(props: UsageProps) {
  const { kind = "tokens", locale = "en-US", currency = "USD", agent = "The agent", period, messages, format } = props;
  const state = read(props);
  const fmt = useFormat(kind, locale, currency, format);
  const label = props.label ?? (kind === "money" ? "Budget" : "Context window");
  const limitText = fmt.short(state.limit);
  const left = Math.max(state.limit - state.used, 0);
  const unit = kind === "money" ? (period ?? "") : "tokens";
  const message =
    messages?.[state.tone] ?? defaultMessage(state.tone, state.full, kind, agent, limitText, fmt.short(left), period);
  const valueText = `${fmt.full(state.used)} of ${fmt.full(state.limit)}${unit ? ` ${unit}` : ""}, ${state.percent}%`;
  return { ...state, kind, fmt, label, limitText, left, unit, message, valueText };
}

/** Says threshold crossings and compaction results, nothing else, so streaming stays quiet. */
function useAnnouncement(usage: ReturnType<typeof useUsage>, compaction: UsageCompaction | undefined) {
  const [text, setText] = useState("");
  const said = useRef(0);
  const last = useRef({ rank: RANK[usage.tone], status: compaction?.status });
  const rank = RANK[usage.tone];
  const status = compaction?.status;
  const { label, percent, message, fmt, unit } = usage;
  const before = compaction?.status === "done" ? compaction.before : 0;
  const after = compaction?.status === "done" ? compaction.after : 0;
  const error = compaction?.status === "failed" ? compaction.error : undefined;

  useEffect(() => {
    const prev = last.current;
    last.current = { rank, status };
    let next: string | null = null;
    if (status !== prev.status && status === "done") {
      next = `Compacted from ${fmt.short(before)} to ${fmt.short(after)} ${unit}.`;
    } else if (status !== prev.status && status === "failed") {
      next = error ?? "Couldn’t compact the conversation. Nothing was lost.";
    } else if (rank > prev.rank) {
      next = `${label} ${percent}% used. ${message}`;
    }
    if (next === null) return;
    // A zero-width space on every other message, so saying the same thing twice is heard twice.
    const line = next + (said.current++ % 2 ? "\u200b" : "");
    // Set a frame later, outside the commit, so the change lands in a region that already exists.
    const frame = requestAnimationFrame(() => setText(line));
    return () => cancelAnimationFrame(frame);
    // Only a crossing or a new result speaks; the figures it quotes don't.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rank, status]);

  return text;
}

/** Fixed width for a changing figure: the widest text it shows sits underneath, hidden. */
function Reserve({ widest, children, className }: { widest: string; children: ReactNode; className?: string }) {
  return (
    <span className={className ? `${styles.reserve} ${className}` : styles.reserve}>
      <span className={styles.sizer} aria-hidden="true">
        {widest}
      </span>
      <span className={styles.reserved}>{children}</span>
    </span>
  );
}

function springPoints(el: Element) {
  const raw = getComputedStyle(el).getPropertyValue("--ui-ease-glide").trim();
  const points = raw.startsWith("linear(") ? raw.slice(7, -1).split(",").map((p) => parseFloat(p)) : [];
  return points.length > 1 && points.every(Number.isFinite) ? points : null;
}

function ease(points: number[] | null, t: number) {
  if (!points) return 1 - Math.pow(1 - t, 5);
  const at = t * (points.length - 1);
  const i = Math.min(Math.floor(at), points.length - 2);
  return points[i] + (points[i + 1] - points[i]) * (at - i);
}

/** The compacted figure counts down from where it was, on the same spring as the bar. */
function CountDown({ from, to, format }: { from: number; to: number; format: (v: number) => string }) {
  const ref = useRef<HTMLSpanElement>(null);
  const formatRef = useRef(format);
  useLayoutEffect(() => {
    formatRef.current = format;
  });

  useLayoutEffect(() => {
    const el = ref.current;
    const node = el?.firstChild;
    if (!el || !node || node.nodeType !== Node.TEXT_NODE || from === to) return;
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    // Writes the text node React rendered, so React's own updates still land on it.
    const write = (v: number) => (node.nodeValue = formatRef.current(v));
    const raw = getComputedStyle(el).getPropertyValue("--ui-dur-glide").trim();
    const duration = (raw.endsWith("ms") ? parseFloat(raw) : parseFloat(raw) * 1000) || 320;
    const points = springPoints(el);
    const start = performance.now();
    let frame = 0;
    write(from);
    const tick = (now: number) => {
      const t = Math.min((now - start) / duration, 1);
      write(from + (to - from) * ease(points, t));
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(frame);
      write(to);
    };
  }, [from, to]);

  return (
    <span ref={ref} className={styles.count}>
      {format(to)}
    </span>
  );
}

/** The breakdown: figure, segmented bar, legend, what happens next and what to do. */
export function UsageBreakdown({ className, announce = true, titleId, figureId, ...props }: UsageBreakdownProps) {
  const { segments = [], onCompact, compactLabel = "Compact conversation", compaction } = props;
  const usage = useUsage(props);
  const { fmt, tone, unit } = usage;
  const ownId = useId();
  const title = titleId ?? `${ownId}-title`;
  const figure = figureId ?? `${ownId}-figure`;
  const resultRef = useRef<HTMLParagraphElement>(null);
  const announcement = useAnnouncement(usage, compaction);

  // The bar's scale: the limit, or what's used once it's gone over.
  const scale = Math.max(usage.limit, usage.used) || 1;
  const listed = segments.length > 0;
  const parts = segments.filter((s) => Number.isFinite(s.value) && s.value > 0);
  const counted = parts.reduce((sum, s) => sum + s.value, 0);
  const rest = usage.used - counted;
  const other = { id: OTHER, label: listed ? "Other" : "Used", value: rest };
  const shown = rest >= scale / 1000 ? [...parts, other] : parts;
  const bars = shown.map((s, i) => {
    const start = Math.min(shown.slice(0, i).reduce((sum, p) => sum + p.value, 0) / scale, 1);
    return { ...s, start, end: Math.min(start + s.value / scale, 1) };
  });
  // Where the free track starts.
  const usedEnd = bars.length ? bars[bars.length - 1].end : 0;

  const status = compaction?.status;
  const running = status === "running";
  const failed = status === "failed";
  const done = compaction?.status === "done" && tone === "calm" ? compaction : null;
  const showAction = !!onCompact && !done && (tone !== "calm" || running || failed);

  // The button that had focus is replaced by the result; focus follows it.
  const wasRunning = useRef(running);
  useLayoutEffect(() => {
    const active = document.activeElement;
    const lost = !active || active === document.body;
    if (wasRunning.current && done && lost) resultRef.current?.focus({ preventScroll: true });
    wasRunning.current = running;
  }, [running, done]);

  return (
    <section
      className={className ? `${styles.breakdown} ${className}` : styles.breakdown}
      data-tone={tone}
      aria-labelledby={title}
    >
      <div className={styles.head}>
        <span id={title} className={styles.title}>
          {usage.label}
        </span>
        <p id={figure} className={styles.figure}>
          <span className={styles.srOnly}>{usage.valueText}</span>
          <span className={styles.figureLine} aria-hidden="true">
            {/* Not reserved: the words after it ride the morph's width spring instead of a gap. */}
            <span className={styles.used}>
              <TextMorph>{fmt.short(usage.used)}</TextMorph>
            </span>
            <span className={styles.of}>
              of {usage.limitText}
              {unit ? ` ${unit}` : ""}
            </span>
            <Reserve widest="100%" className={styles.percent}>
              <TextMorph>{`${usage.percent}%`}</TextMorph>
            </Reserve>
          </span>
        </p>
      </div>

      <div
        role="meter"
        aria-labelledby={title}
        aria-valuemin={0}
        aria-valuemax={usage.limit}
        aria-valuenow={Math.min(usage.used, usage.limit)}
        aria-valuetext={usage.valueText}
        className={styles.bar}
        style={{ "--used": usedEnd } as CSSProperties}
      >
        {bars.map((b, i) => (
          <span
            key={b.id}
            className={styles.segment}
            data-index={!listed ? "used" : b.id === OTHER ? "other" : i}
            data-last={i === bars.length - 1 || undefined}
            data-full={usedEnd >= 1 || undefined}
            style={{ "--start": b.start, "--end": b.end } as CSSProperties}
          />
        ))}
      </div>

      {listed && (
        <ul className={styles.legend} aria-label={`What’s using the ${usage.label.toLocaleLowerCase()}`}>
          {bars.map((b, i) => (
            <li key={b.id} className={styles.item}>
              <span className={styles.swatch} data-index={b.id === OTHER ? "other" : i} aria-hidden="true" />
              <span className={styles.name}>{b.label}</span>
              <span className={styles.amount}>
                <TextMorph>{fmt.short(b.value)}</TextMorph>
              </span>
            </li>
          ))}
          <li className={styles.item} data-free>
            <span className={styles.swatch} data-free aria-hidden="true" />
            <span className={styles.name}>{usage.kind === "money" ? "Left" : "Free"}</span>
            <span className={styles.amount}>
              <TextMorph>{fmt.short(usage.left)}</TextMorph>
            </span>
          </li>
        </ul>
      )}

      <AnimatedSize>
        <div className={styles.status}>
          {done ? (
            <p key="result" ref={resultRef} tabIndex={-1} className={styles.result} data-enter>
              <Icon name="check-circle" />
              <span>
                Compacted:{" "}
                <span className={styles.figures}>
                  {fmt.short(done.before)} →{" "}
                  <Reserve widest={fmt.short(done.before)} className={styles.countBox}>
                    <CountDown from={done.before} to={done.after} format={fmt.short} />
                  </Reserve>
                </span>
              </span>
            </p>
          ) : (
            <p key={tone} className={styles.message} data-enter={tone !== "calm" || undefined}>
              <Icon name={TONE_ICON[tone]} />
              <span>{usage.message}</span>
            </p>
          )}

          {compaction?.status === "failed" && (
            <p className={styles.error}>
              {compaction.error ?? "Couldn’t compact the conversation. Nothing was lost; try again."}
            </p>
          )}

          {showAction && (
            <Button
              className={styles.action}
              variant={tone === "danger" && !running ? "primary" : "secondary"}
              busy={running}
              busyLabel="Compacting…"
              onClick={onCompact}
            >
              {failed ? "Try again" : compactLabel}
            </Button>
          )}
        </div>
      </AnimatedSize>

      {announce && (
        <span role="status" className={styles.srOnly}>
          {announcement}
        </span>
      )}
    </section>
  );
}

/** A small ring and percentage for a toolbar; opens to the breakdown. */
export function UsageMeter({
  indicator = "ring",
  side = "top",
  align = "start",
  open,
  defaultOpen,
  onOpenChange,
  className,
  ...props
}: UsageMeterProps) {
  const usage = useUsage(props);
  const id = useId();
  const titleId = `${id}-title`;
  const figureId = `${id}-figure`;
  const announcement = useAnnouncement(usage, props.compaction);
  const state = usage.tone === "danger" ? (usage.full ? ", full" : ", nearly full") : usage.tone === "warning" ? ", running low" : "";

  return (
    <span className={className ? `${styles.root} ${className}` : styles.root}>
      <Popover
        labelledBy={`${titleId} ${figureId}`}
        side={side}
        align={align}
        open={open}
        defaultOpen={defaultOpen}
        onOpenChange={onOpenChange}
        className={styles.panel}
        trigger={
          <button
            type="button"
            className={styles.trigger}
            data-tone={usage.tone}
            aria-label={`${usage.label}: ${usage.percent}% used${state}`}
          >
            {indicator === "ring" ? (
              <svg className={styles.ring} viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
                <circle className={styles.ringTrack} cx="8" cy="8" r="6" />
                <circle
                  className={styles.ringArc}
                  cx="8"
                  cy="8"
                  r="6"
                  pathLength={100}
                  data-empty={usage.used <= 0 || undefined}
                  style={{ strokeDashoffset: 100 - usage.fraction * 100 }}
                />
              </svg>
            ) : (
              <span
                className={styles.miniBar}
                aria-hidden="true"
                style={{ "--usage": usage.fraction } as CSSProperties}
              />
            )}
            <Reserve widest="100%" className={styles.triggerPercent}>
              <TextMorph>{`${usage.percent}%`}</TextMorph>
            </Reserve>
          </button>
        }
      >
        <UsageBreakdown {...props} announce={false} titleId={titleId} figureId={figureId} />
      </Popover>
      <span role="status" className={styles.srOnly}>
        {announcement}
      </span>
    </span>
  );
}

@layer theme, base, components, utilities;

.sweep {
  composes: sweep from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  /* The screen is its own container: the nav moves beside the sections once
     the screen, not the window, is wide enough. */
  .root {
    /* Where the nav sticks and where a jumped-to section lands. Set it to
       your header's height plus 24 if the page has a sticky header. */
    --agent-settings-top: var(--ui-space-6);
    /* Links take a small button's padding; their text lines up with the title. */
    --agent-settings-nav-inset: 14px;
    container: agent-settings / inline-size;
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
  }

  /* ---------- Title ---------- */

  .header {
    display: grid;
    gap: var(--ui-space-2);
    padding-bottom: var(--ui-space-6);
  }

  .title {
    margin: 0;
    font-family: var(--ui-font-display);
    font-size: var(--ui-text-display);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-display);
    letter-spacing: var(--ui-tracking-title);
    text-wrap: balance;
  }

  .lede {
    max-width: var(--ui-measure);
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  /* ---------- Layout and nav ---------- */

  /* Phones: the links sit in a wrapping row above the sections, 32 clear. */
  .layout {
    display: grid;
    gap: var(--ui-space-6);
  }

  .navList {
    display: flex;
    flex-wrap: wrap;
    gap: 2px;
    margin: 0;
    /* The links' padding hangs outside, so their text starts at the title's edge. */
    margin-inline-start: calc(var(--agent-settings-nav-inset) * -1);
    padding: 0;
    list-style: none;
  }

  .navLink {
    position: relative;
    display: flex;
    align-items: center;
    height: var(--ui-control-sm);
    padding-inline: var(--agent-settings-nav-inset);
    border-radius: var(--ui-radius-sm);
    color: var(--ui-muted);
    /* One weight in every state, so marking the current link moves nothing. */
    font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    text-decoration: none;
    white-space: nowrap;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--ui-dur-instant) var(--ui-ease-color),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .navLink:hover {
      color: var(--ui-foreground);
    }
  }

  .navLink:active {
    background: var(--ui-fill-strong);
    transition-duration: var(--ui-dur-press);
  }

  .navLink:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .navLink[aria-current="true"] {
    background: var(--ui-fill);
    color: var(--ui-foreground);
  }

  /* Links reach 40px under a finger. */
  @media (pointer: coarse) {
    .navLink::after {
      content: "";
      position: absolute;
      inset: -3px 0;
    }
  }

  /* Wide: a column of links that stays in view and marks where you are. The
     nav stretches the full height of the sections, so its list has room to stick. */
  @container agent-settings (min-width: 640px) {
    .layout {
      grid-template-columns: 144px minmax(0, 1fr);
      column-gap: var(--ui-space-6);
    }
    .navList {
      position: sticky;
      top: var(--agent-settings-top);
      flex-direction: column;
      flex-wrap: nowrap;
    }
  }

  .content {
    container: agent-settings-content / inline-size;
    display: grid;
    gap: var(--ui-space-8);
    min-width: 0;
  }

  /* ---------- Sections ---------- */

  .section {
    display: grid;
    gap: var(--ui-space-5);
    min-width: 0;
    scroll-margin-top: var(--agent-settings-top);
  }

  .sectionHead,
  .subHead {
    display: grid;
    gap: var(--ui-space-1);
  }

  .sectionTitle {
    margin: 0;
    font-size: var(--ui-text-2xl);
    font-weight: var(--ui-weight-semibold);
    line-height: var(--ui-leading-2xl);
    letter-spacing: var(--ui-tracking-heading);
    text-wrap: balance;
  }

  .sectionTitle:focus {
    outline: none;
  }

  .intro {
    max-width: var(--ui-measure);
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .subsections {
    display: grid;
    gap: var(--ui-space-7);
  }

  .subsection {
    display: grid;
    gap: var(--ui-space-4);
    min-width: 0;
  }

  .subTitle {
    margin: 0;
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
    text-wrap: balance;
  }

  /* Embedded as it is, at the column's full width. */
  .content .connections {
    max-width: none;
  }

  /* ---------- Rows ---------- */

  /* Hairlines between rows, none above the first or under the last. */
  .rows {
    display: grid;
    min-width: 0;
  }

  .rows > * {
    padding-block: var(--ui-space-4);
  }

  .rows > :first-child {
    padding-top: 0;
  }

  .rows > :last-child {
    padding-bottom: 0;
  }

  .rows > * + * {
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  .row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    column-gap: var(--ui-space-5);
    align-items: center;
    min-width: 0;
  }

  /* Beside a 48px field, the label sits level with the field's middle. */
  .row[data-align="field"] {
    align-items: start;
  }

  .row[data-align="field"] .text {
    padding-top: calc((var(--ui-control-md) - var(--ui-leading-md)) / 2);
  }

  .text {
    display: grid;
    gap: 2px;
    min-width: 0;
  }

  /* The status rides after the label, wrapping under it before the label is cut. */
  .labelLine {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 2px var(--ui-space-2);
    min-width: 0;
  }

  .label {
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .description {
    max-width: var(--ui-measure);
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .focusTarget:focus {
    outline: none;
  }

  .control {
    display: flex;
    justify-content: flex-end;
    min-width: 0;
  }

  .rowBody {
    grid-column: 1 / -1;
    min-width: 0;
    padding-top: var(--ui-space-3);
  }

  /* Narrow column: the control drops under its text. */
  @container agent-settings-content (max-width: 440px) {
    .row {
      grid-template-columns: minmax(0, 1fr);
      row-gap: var(--ui-space-3);
    }
    .row[data-align="field"] .text {
      padding-top: 0;
    }
    .control {
      justify-content: flex-start;
    }
    /* The picker's label starts at the text's edge; its fill hangs outside. */
    .model {
      margin-inline-start: -14px;
    }
    .rowBody {
      padding-top: 0;
    }
  }

  /* "Saving…" waits 300ms before it shows, so a quick save shows only "Saved". */
  .status {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-1);
    min-width: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    opacity: 0;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-exit);
  }

  .status[data-shown] {
    opacity: 1;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .status[data-shown][data-state="saving"] {
    transition-delay: 300ms;
  }

  .status[data-state="failed"] {
    color: var(--ui-danger-text);
  }

  /* 14px beside 13px text. */
  .statusIcon {
    flex-shrink: 0;
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
  }

  .status[data-state="saved"] .statusIcon {
    color: var(--ui-success);
  }

  .status[data-state="failed"] .statusIcon {
    color: var(--ui-danger);
  }

  /* ---------- Model, permissions, limit ---------- */

  /* Held to its own height, so the "Allow" that can't be picked stays in line. */
  .policy {
    flex-shrink: 0;
  }

  /* ---------- Always allowed ---------- */

  /* Removed rows and groups close through grid-template-rows, so nothing jumps. */
  .group,
  .toolRow {
    display: grid;
    grid-template-rows: 1fr;
  }

  .group[data-closing],
  .toolRow[data-closing] {
    grid-template-rows: 0fr;
    opacity: 0;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      grid-template-rows var(--ui-dur-base) var(--ui-ease-collapse) var(--ui-dur-instant);
  }

  .clip {
    min-height: 0;
    overflow: hidden;
  }

  .groupInner {
    display: grid;
  }

  /* Space between groups sits inside the clip, so it closes with the group. */
  .group + .group .groupInner {
    padding-top: var(--ui-space-5);
  }

  .groupLabel {
    margin: 0;
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-sm);
  }

  .tools {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .toolInner {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    column-gap: var(--ui-space-5);
    align-items: center;
    padding-block: var(--ui-space-3);
  }

  .toolRow + .toolRow .toolInner {
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  .toolText {
    display: grid;
    gap: 2px;
    min-width: 0;
  }

  .toolLine {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 2px var(--ui-space-2);
    min-width: 0;
  }

  .toolName {
    min-width: 0;
    color: var(--ui-foreground);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-code);
    line-height: var(--ui-leading-md);
    overflow-wrap: anywhere;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .toolBadge {
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .toolRow[data-revoked] .toolName {
    color: var(--ui-muted);
  }

  .toolRow[data-revoked] .toolBadge {
    opacity: 0.5;
  }

  .toolDescription {
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .toolDescription[data-error] {
    color: var(--ui-danger-text);
  }

  .toolAction {
    display: flex;
    justify-content: flex-end;
  }

  .revoked {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    white-space: nowrap;
  }

  .revoked[data-enter] {
    animation: agent-settings-fade var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes agent-settings-fade {
    from {
      opacity: 0;
    }
  }

  .revokedText:focus {
    outline: none;
  }

  .dot {
    color: var(--ui-subtle);
  }

  /* The ghost button's label sits as close to the dot as the dot to "Revoked". */
  .undo {
    margin-inline-start: calc(6px - 20px);
  }

  .empty {
    max-width: var(--ui-measure);
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  /* ---------- Memory ---------- */

  .notes {
    display: grid;
    gap: var(--ui-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* A small mark on each note's first line. */
  .notes li {
    position: relative;
    padding-inline-start: var(--ui-space-4);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .notes li::before {
    content: "";
    position: absolute;
    top: calc(var(--ui-leading-md) / 2 - 2px);
    inset-inline-start: 2px;
    width: 4px;
    height: 4px;
    border-radius: var(--ui-radius-full);
    background: var(--ui-subtle);
  }

  .confirm {
    display: grid;
    gap: var(--ui-space-3);
    padding: var(--ui-space-3);
    border-radius: var(--ui-radius-md);
    background: var(--ui-fill);
  }

  .notes + .confirm {
    margin-top: var(--ui-space-4);
  }

  .confirm[data-enter] {
    animation: agent-settings-in var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes agent-settings-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }

  .confirm p {
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .confirm strong {
    font-weight: var(--ui-weight-semibold);
  }

  .confirm .failure {
    color: var(--ui-danger-text);
  }

  .confirmActions {
    display: flex;
    justify-content: flex-end;
    gap: var(--ui-space-2);
  }

  @container agent-settings-content (max-width: 440px) {
    .confirmActions > * {
      flex: 1;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .group[data-closing],
    .toolRow[data-closing] {
      transition: opacity var(--ui-dur-instant) var(--ui-ease-exit);
    }
    .confirm[data-enter] {
      animation: agent-settings-fade var(--ui-dur-fast) var(--ui-ease-enter);
    }
  }
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from "react";
import { AnimatedSize } from "../animated-size/animated-size";
import { Badge } from "../badge/badge";
import { Button } from "../button/button";
import { Connections } from "../connections/connections";
import { Icon } from "../icons/icons";
import { ModelPicker, type ModelOption } from "../model-picker/model-picker";
import { NumberInput } from "../number-input/number-input";
import { Segment, SegmentedControl } from "../segmented-control/segmented-control";
import { Switch } from "../switch/switch";
import { UsageBreakdown, type UsageSegment } from "../usage-meter/usage-meter";
import styles from "./agent-settings.module.css";

export type AgentSettingsSection = "model" | "connections" | "permissions" | "usage" | "memory";

/** What a tool does to the world, as tool approval names it. */
export type ToolEffect = "read" | "change" | "send" | "delete" | "spend";

/** `ask`: every time. `allow`: without asking. */
export type AskPolicy = "ask" | "allow";

/** Only reads and changes can go without asking; sends, deletes and spends always ask. */
export type EffectPolicy = { read: AskPolicy; change: AskPolicy };

/** The values the person sets. Leave one out and its row (or section) goes with it. */
export type AgentSettingsValue = {
  /** The id of a model in `models`. */
  model?: string;
  policy?: EffectPolicy;
  /** In currency units: 10 is $10.00 with USD. */
  dailyLimit?: number;
  /** Whether the agent keeps notes between conversations. */
  remember?: boolean;
};

/** A tool the person chose "Always allow" for. */
export type AllowedTool = {
  id: string;
  /** The server's name, as Connections shows it: "Acme". Tools are grouped by it. */
  server: string;
  /** As the server names it: `list_bookings`. */
  tool: string;
  effect: ToolEffect;
  /** One line on what it does. */
  description?: string;
};

export type MemoryNote = {
  id: string;
  /** One remembered fact, as a sentence: "Ben Ito is vegetarian." */
  text: string;
};

export type AgentSpending = {
  /** Spent today, in currency units. */
  used: number;
  /** What it was spent on, as in the usage meter. */
  segments?: UsageSegment[];
};

type Result = void | Promise<unknown>;

type ConnectionsProps = Omit<ComponentProps<typeof Connections>, "agent" | "className">;

type AgentSettingsProps = {
  /** The agent's name, used in sentences: "Copper asks every time". */
  agent: string;
  /** Controlled. */
  settings: AgentSettingsValue;
  /** Called with the one value that changed. Return a promise to show "Saving…" until it settles; a rejection shows its message. */
  onChange?: (patch: Partial<AgentSettingsValue>) => Result;
  /** The models to choose from, as in the model picker. */
  models?: ModelOption[];
  /** Passed to the Connections component as they are. */
  connections?: ConnectionsProps;
  /** Tools set to "Always allow". */
  allowed?: AllowedTool[];
  /** Remove the tool from `allowed`. A rejection puts the row back with its message. */
  onRevoke?: (tool: AllowedTool) => Result;
  /** Undo a revoke: add the tool back where it was. Leave out to offer no Undo. */
  onRestore?: (tool: AllowedTool) => Result;
  /** Replaces the line under Reads, Changes, Sends, Deletes and Spends money. */
  effectNotes?: Partial<Record<ToolEffect, string>>;
  /** Today's spending, for the breakdown above the daily limit. */
  spending?: AgentSpending;
  /** The highest daily limit the field takes. Default 500. */
  maxDailyLimit?: number;
  /** ISO 4217 code. Default "USD". */
  currency?: string;
  /** Fixed so server and browser format numbers alike. Default "en-US". */
  locale?: string;
  /** What the agent remembers, newest first. */
  memories?: MemoryNote[];
  /** Clear every note, then pass `memories={[]}`. Leave out to hide Clear memory. */
  onClearMemory?: () => Result;
  /** Which sections to show, in this order. Default: all five, each when its values are there. */
  sections?: AgentSettingsSection[];
  /** Default "Copper settings", from `agent`. */
  title?: ReactNode;
  /** A line under the title. */
  description?: ReactNode;
  /** The title's level; sections are one below. Default 1. */
  headingLevel?: 1 | 2 | 3 | 4;
  /** Starts every section's id, so `#agent-settings-memory` links straight to it. */
  idPrefix?: string;
  className?: string;
};

const ALL_SECTIONS: AgentSettingsSection[] = ["model", "connections", "permissions", "usage", "memory"];

const SECTION_TITLE: Record<AgentSettingsSection, string> = {
  model: "Model",
  connections: "Connections",
  permissions: "Permissions",
  usage: "Usage & budget",
  memory: "Memory",
};

const EFFECTS: Record<ToolEffect, { label: string; weighty: boolean; note: (agent: string) => string }> = {
  read: { label: "Reads", weighty: false, note: () => "Looking things up. Nothing changes." },
  change: { label: "Changes", weighty: false, note: () => "Edits that can be changed back, like a draft or a list." },
  send: {
    label: "Sends",
    weighty: true,
    note: (agent) => `Messages and posts can’t be taken back once they’re out, so ${agent} always asks.`,
  },
  delete: { label: "Deletes", weighty: true, note: (agent) => `Deleted things don’t come back, so ${agent} always asks.` },
  spend: {
    label: "Spends money",
    weighty: true,
    note: (agent) => `Money moves the moment a payment or refund runs, so ${agent} always asks.`,
  },
};

const EFFECT_ORDER: ToolEffect[] = ["read", "change", "send", "delete", "spend"];

/** How long "Saved" stays. */
const SAVED_FOR = 2400;
/** How long "Revoked · Undo" stays once nothing is on it. */
const UNDO_FOR = 6000;

function plural(n: number, one: string) {
  return `${n} ${n === 1 ? one : `${one}s`}`;
}

function messageOf(reason: unknown, fallback: string) {
  if (typeof reason === "string" && reason) return reason;
  if (reason instanceof Error && reason.message) return reason.message;
  return fallback;
}

function isPromise(value: unknown): value is Promise<unknown> {
  return !!value && typeof (value as Promise<unknown>).then === "function";
}

function Heading({ level, ...props }: { level: number } & ComponentProps<"h2">) {
  const Tag = `h${Math.min(Math.max(level, 1), 6)}` as "h2";
  return <Tag {...props} />;
}

/** One polite region for the whole screen. */
function useAnnouncer() {
  const [text, setText] = useState("");
  const said = useRef(0);
  const announce = useCallback((line: string) => {
    // A zero-width space on every other message, so saying the same thing twice is heard twice.
    setText(line + (said.current++ % 2 ? "​" : ""));
  }, []);
  return { text, announce };
}

type Save = { state: "saving" | "saved" | "failed"; message?: string };

/** Each row's save: "Saving…" past 300ms, "Saved" for a moment, or what went wrong. */
function useSaves(announce: (line: string) => void) {
  const [saves, setSaves] = useState<Partial<Record<string, Save>>>({});
  const runs = useRef(new Map<string, number>());
  const timers = useRef(new Map<string, number>());

  useEffect(() => {
    const pending = timers.current;
    return () => pending.forEach((t) => window.clearTimeout(t));
  }, []);

  const settle = useCallback((key: string, save: Save) => {
    setSaves((s) => ({ ...s, [key]: save }));
    window.clearTimeout(timers.current.get(key));
    if (save.state !== "saved") return;
    timers.current.set(
      key,
      window.setTimeout(() => setSaves((s) => ({ ...s, [key]: undefined })), SAVED_FOR),
    );
  }, []);

  const save = useCallback(
    (key: string, run: () => Result, said: string) => {
      const n = (runs.current.get(key) ?? 0) + 1;
      runs.current.set(key, n);
      const fail = (reason: unknown) => {
        const message = messageOf(reason, "Didn’t save. Try again.");
        settle(key, { state: "failed", message });
        announce(message);
      };
      let result: Result;
      try {
        result = run();
      } catch (reason) {
        fail(reason);
        return;
      }
      if (!isPromise(result)) {
        settle(key, { state: "saved" });
        announce(said);
        return;
      }
      settle(key, { state: "saving" });
      // Only the latest change to a row speaks for it.
      result.then(
        () => {
          if (runs.current.get(key) !== n) return;
          settle(key, { state: "saved" });
          announce(said);
        },
        (reason) => {
          if (runs.current.get(key) === n) fail(reason);
        },
      );
    },
    [announce, settle],
  );

  return { saves, save };
}

/** Beside a row's label. Keeps its last words while it fades. */
function Status({ save }: { save?: Save }) {
  const [last, setLast] = useState(save);
  if (save && save !== last) setLast(save);
  return (
    <span className={styles.status} data-state={last?.state} data-shown={save ? "" : undefined}>
      {last?.state === "saving" && <span className={styles.sweep}>Saving…</span>}
      {last?.state === "saved" && (
        <>
          <Icon name="check" className={styles.statusIcon} />
          Saved
        </>
      )}
      {last?.state === "failed" && (
        <>
          <Icon name="alert" className={styles.statusIcon} />
          {last.message}
        </>
      )}
    </span>
  );
}

type RowIds = { label: string; description: string };

function Row({
  label,
  description,
  save,
  control,
  align = "center",
  children,
}: {
  label: ReactNode;
  description?: ReactNode;
  save?: Save;
  control?: (ids: RowIds) => ReactNode;
  /** `field`: the label lines up with a 48px field instead of the row's middle. */
  align?: "center" | "field";
  children?: ReactNode;
}) {
  const id = useId();
  const ids = { label: `${id}-label`, description: `${id}-description` };
  return (
    <div className={styles.row} data-align={align}>
      <div className={styles.text}>
        <div className={styles.labelLine}>
          <span id={ids.label} className={styles.label}>
            {label}
          </span>
          <Status save={save} />
        </div>
        {description && (
          <p id={ids.description} className={styles.description}>
            {description}
          </p>
        )}
      </div>
      {control && <div className={styles.control}>{control(ids)}</div>}
      {children && <div className={styles.rowBody}>{children}</div>}
    </div>
  );
}

function Section({
  id,
  level,
  title,
  intro,
  children,
}: {
  id: string;
  level: number;
  title: string;
  intro?: ReactNode;
  children: ReactNode;
}) {
  return (
    <section id={id} className={styles.section} aria-labelledby={`${id}-title`}>
      <div className={styles.sectionHead}>
        <Heading level={level} id={`${id}-title`} className={styles.sectionTitle}>
          {title}
        </Heading>
        {intro && <p className={styles.intro}>{intro}</p>}
      </div>
      {children}
    </section>
  );
}

/* ---------- Always allowed ---------- */

type Revoked = { tool: AllowedTool; index: number; closing: boolean };

type ToolRowProps = {
  tool: AllowedTool;
  agent: string;
  revoked: boolean;
  closing: boolean;
  error?: string;
  canUndo: boolean;
  onRevoke: (tool: AllowedTool) => void;
  onUndo: (tool: AllowedTool) => void;
  onExpire: (id: string) => void;
  onGone: (id: string) => void;
};

function ToolRow({ tool, agent, revoked, closing, error, canUndo, onRevoke, onUndo, onExpire, onGone }: ToolRowProps) {
  const rowRef = useRef<HTMLLIElement>(null);
  const revokeRef = useRef<HTMLButtonElement>(null);
  const undoRef = useRef<HTMLButtonElement>(null);
  const revokedRef = useRef<HTMLSpanElement>(null);
  const [focused, setFocused] = useState(false);
  const [hovered, setHovered] = useState(false);
  const refocus = useRef(false);
  const effect = EFFECTS[tool.effect];

  // Undo waits while it's being looked at or reached for.
  const held = focused || hovered;
  useEffect(() => {
    if (!revoked || closing || held) return;
    const timer = window.setTimeout(() => onExpire(tool.id), UNDO_FOR);
    return () => window.clearTimeout(timer);
  }, [revoked, closing, held, onExpire, tool.id]);

  // Gone once its space has closed; the timer covers reduced motion and missed events.
  useEffect(() => {
    if (!closing) return;
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const timer = window.setTimeout(() => onGone(tool.id), reduce ? 0 : 700);
    return () => window.clearTimeout(timer);
  }, [closing, onGone, tool.id]);

  // The button pressed is replaced by the other one; focus follows.
  useLayoutEffect(() => {
    if (!refocus.current) return;
    refocus.current = false;
    if (revoked) (undoRef.current ?? revokedRef.current)?.focus();
    else revokeRef.current?.focus();
  }, [revoked]);

  function act(fn: () => void) {
    refocus.current = !!rowRef.current?.contains(document.activeElement);
    fn();
  }

  const description = error ?? (revoked ? `${agent} asks before using it again.` : tool.description);

  return (
    <li
      ref={rowRef}
      className={styles.toolRow}
      data-revoked={revoked || undefined}
      data-closing={closing || undefined}
      inert={closing || undefined}
      onFocus={() => setFocused(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setFocused(false);
      }}
      onPointerEnter={(e) => e.pointerType === "mouse" && setHovered(true)}
      onPointerLeave={() => setHovered(false)}
      onTransitionEnd={(e) => {
        if (closing && e.target === e.currentTarget && e.propertyName === "grid-template-rows") onGone(tool.id);
      }}
    >
      <div className={styles.clip}>
        <div className={styles.toolInner}>
          <div className={styles.toolText}>
            <div className={styles.toolLine}>
              <code className={styles.toolName}>{tool.tool}</code>
              <Badge size="sm" tone={effect.weighty ? "warning" : "neutral"} dot={effect.weighty} className={styles.toolBadge}>
                {effect.label}
              </Badge>
            </div>
            {description && (
              <p className={styles.toolDescription} data-error={error ? "" : undefined}>
                {description}
              </p>
            )}
          </div>
          <div className={styles.toolAction}>
            {revoked ? (
              <span key="revoked" className={styles.revoked} data-enter>
                <span ref={revokedRef} tabIndex={-1} className={styles.revokedText}>
                  Revoked
                </span>
                {canUndo && (
                  <>
                    <span className={styles.dot} aria-hidden="true">
                      ·
                    </span>
                    <Button
                      ref={undoRef}
                      variant="ghost"
                      className={styles.undo}
                      aria-label={`Undo revoking ${tool.tool}`}
                      onClick={() => act(() => onUndo(tool))}
                    >
                      Undo
                    </Button>
                  </>
                )}
              </span>
            ) : (
              <Button
                key="revoke"
                ref={revokeRef}
                variant="ghost"
                className={styles.revoke}
                aria-label={`Revoke ${tool.tool}`}
                onClick={() => act(() => onRevoke(tool))}
              >
                Revoke
              </Button>
            )}
          </div>
        </div>
      </div>
    </li>
  );
}

function AllowedTools({
  agent,
  allowed,
  onRevoke,
  onRestore,
  announce,
}: {
  agent: string;
  allowed: AllowedTool[];
  onRevoke?: (tool: AllowedTool) => Result;
  onRestore?: (tool: AllowedTool) => Result;
  announce: (line: string) => void;
}) {
  const baseId = useId();
  // Revoked tools stay in place, with Undo, until they time out and close.
  const [revoked, setRevoked] = useState<Revoked[]>([]);
  const [errors, setErrors] = useState<Partial<Record<string, string>>>({});

  const groups = useMemo(() => {
    const ids = new Set(allowed.map((t) => t.id));
    const rows = [...allowed];
    for (const r of [...revoked].sort((a, b) => a.index - b.index)) {
      if (!ids.has(r.tool.id)) rows.splice(Math.min(r.index, rows.length), 0, r.tool);
    }
    const byServer = new Map<string, AllowedTool[]>();
    for (const tool of rows) byServer.set(tool.server, [...(byServer.get(tool.server) ?? []), tool]);
    return [...byServer.entries()];
  }, [allowed, revoked]);

  const find = (id: string) => revoked.find((r) => r.tool.id === id);
  const drop = (id: string) => setRevoked((r) => r.filter((x) => x.tool.id !== id));
  const clearError = (id: string) => setErrors((e) => ({ ...e, [id]: undefined }));

  function revoke(tool: AllowedTool) {
    const index = allowed.findIndex((t) => t.id === tool.id);
    clearError(tool.id);
    setRevoked((r) => [...r.filter((x) => x.tool.id !== tool.id), { tool, index, closing: false }]);
    announce(`Revoked ${tool.tool}. ${agent} will ask before using it.`);
    const fail = (reason: unknown) => {
      drop(tool.id);
      const message = messageOf(reason, `Couldn’t revoke ${tool.tool}. Try again.`);
      setErrors((e) => ({ ...e, [tool.id]: message }));
      announce(message);
    };
    try {
      const result = onRevoke?.(tool);
      if (isPromise(result)) result.catch(fail);
    } catch (reason) {
      fail(reason);
    }
  }

  function undo(tool: AllowedTool) {
    const was = find(tool.id);
    drop(tool.id);
    announce(`${tool.tool} is always allowed again.`);
    const fail = (reason: unknown) => {
      if (was) setRevoked((r) => [...r.filter((x) => x.tool.id !== tool.id), was]);
      const message = messageOf(reason, `Couldn’t undo. ${tool.tool} is still revoked.`);
      announce(message);
    };
    try {
      const result = onRestore?.(tool);
      if (isPromise(result)) result.catch(fail);
    } catch (reason) {
      fail(reason);
    }
  }

  const expire = useCallback(
    (id: string) => setRevoked((r) => r.map((x) => (x.tool.id === id ? { ...x, closing: true } : x))),
    [],
  );
  const gone = useCallback((id: string) => setRevoked((r) => r.filter((x) => x.tool.id !== id)), []);

  if (groups.length === 0) {
    return (
      <p className={styles.empty}>
        Nothing yet. When {agent} asks to use a tool, choose Always allow and it shows up here.
      </p>
    );
  }

  return (
    <div className={styles.groups}>
      {groups.map(([server, tools], i) => {
        const labelId = `${baseId}-${i}`;
        const closing = tools.every((t) => find(t.id)?.closing);
        return (
          <div key={server} className={styles.group} data-closing={closing || undefined} inert={closing || undefined}>
            <div className={styles.clip}>
              <div className={styles.groupInner}>
                <p id={labelId} className={styles.groupLabel}>
                  {server}
                </p>
                <ul className={styles.tools} aria-labelledby={labelId}>
                  {tools.map((tool) => {
                    const state = find(tool.id);
                    return (
                      <ToolRow
                        key={tool.id}
                        tool={tool}
                        agent={agent}
                        revoked={!!state}
                        closing={!!state?.closing}
                        error={errors[tool.id]}
                        canUndo={!!onRestore}
                        onRevoke={revoke}
                        onUndo={undo}
                        onExpire={expire}
                        onGone={gone}
                      />
                    );
                  })}
                </ul>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ---------- Memory ---------- */

function Memory({
  agent,
  remember,
  memories,
  onClear,
  save,
  rememberSave,
  announce,
}: {
  agent: string;
  remember?: boolean;
  memories?: MemoryNote[];
  onClear?: () => Result;
  save?: (on: boolean) => void;
  rememberSave?: Save;
  announce: (line: string) => void;
}) {
  const [confirming, setConfirming] = useState(false);
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState<string | null>(null);
  const clearRef = useRef<HTMLButtonElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);
  const emptyRef = useRef<HTMLParagraphElement>(null);
  const cleared = useRef(false);
  const count = memories?.length ?? 0;

  // Nothing left to clear: the confirm closes on its own.
  if (confirming && count === 0) setConfirming(false);

  const wasConfirming = useRef(confirming);
  useLayoutEffect(() => {
    // The safe choice takes focus.
    if (confirming && !wasConfirming.current) cancelRef.current?.focus();
    wasConfirming.current = confirming;
  }, [confirming]);

  // Clear memory is gone with the notes; focus lands on what replaced them.
  useLayoutEffect(() => {
    if (count === 0 && cleared.current) {
      cleared.current = false;
      emptyRef.current?.focus({ preventScroll: true });
    }
  }, [count]);

  function cancel() {
    setConfirming(false);
    setFailure(null);
    requestAnimationFrame(() => clearRef.current?.focus());
  }

  async function clear() {
    setFailure(null);
    const said = `Memory cleared. ${agent} forgot ${plural(count, "note")}.`;
    let result: Result;
    try {
      result = onClear?.();
    } catch (reason) {
      setFailure(messageOf(reason, "Couldn’t clear memory. Try again."));
      return;
    }
    cleared.current = true;
    if (!isPromise(result)) {
      announce(said);
      return;
    }
    setBusy(true);
    try {
      await result;
      announce(said);
    } catch (reason) {
      cleared.current = false;
      setFailure(messageOf(reason, "Couldn’t clear memory. Try again."));
    }
    setBusy(false);
  }

  function onConfirmKey(event: KeyboardEvent) {
    if (event.key === "Escape" && !busy) {
      event.stopPropagation();
      cancel();
    }
  }

  let notesLine: string;
  if (count === 0) notesLine = remember === false ? `${agent} isn’t keeping notes.` : `Nothing yet. Notes show up here as ${agent} makes them.`;
  else if (remember === false) notesLine = `${plural(count, "note")}, kept while remembering is off. Clear them to forget them.`;
  else notesLine = `${plural(count, "note")}, newest first.`;

  return (
    <div className={styles.rows}>
      {remember !== undefined && save && (
        <Row
          label="Remember between conversations"
          description={`${agent} keeps short notes, like names and preferences, and uses them in new conversations.`}
          save={rememberSave}
          control={(ids) => (
            <Switch
              checked={remember}
              aria-labelledby={ids.label}
              aria-describedby={ids.description}
              onChange={(e) => save(e.currentTarget.checked)}
            />
          )}
        />
      )}
      {memories && (
        <Row
          label={`What ${agent} remembers`}
          description={
            <span ref={emptyRef} tabIndex={-1} className={styles.focusTarget}>
              {notesLine}
            </span>
          }
          control={
            onClear && count > 0 && !confirming
              ? () => (
                  <Button ref={clearRef} variant="secondary" onClick={() => setConfirming(true)}>
                    Clear memory
                  </Button>
                )
              : undefined
          }
        >
          {(count > 0 || confirming) && (
            <AnimatedSize>
              {count > 0 && (
                <ul className={styles.notes} aria-label={`What ${agent} remembers`}>
                  {memories.map((note) => (
                    <li key={note.id}>{note.text}</li>
                  ))}
                </ul>
              )}
              {confirming && (
                <div
                  className={styles.confirm}
                  data-enter
                  role="group"
                  aria-label={`Clear everything ${agent} remembers?`}
                  onKeyDown={onConfirmKey}
                >
                  <p>
                    <strong>Clear everything {agent} remembers?</strong> {agent} forgets{" "}
                    {count === 1 ? "this note" : `these ${count} notes`} for good. Your conversations stay.
                  </p>
                  {failure && (
                    <p className={styles.failure} role="alert">
                      {failure}
                    </p>
                  )}
                  <div className={styles.confirmActions}>
                    <Button ref={cancelRef} variant="secondary" onClick={cancel} disabled={busy}>
                      Cancel
                    </Button>
                    <Button variant="danger" busy={busy} busyLabel="Clearing…" onClick={clear}>
                      Clear memory
                    </Button>
                  </div>
                </div>
              )}
            </AnimatedSize>
          )}
        </Row>
      )}
    </div>
  );
}

/* ---------- Section nav ---------- */

/** The section whose top has passed just under the sticky nav, or the last one at the end of the page. */
/** `idList` is the sections' ids, space-separated, so the effect reruns only when they change. */
function useCurrentSection(navRef: RefObject<HTMLUListElement | null>, idList: string) {
  const [current, setCurrent] = useState<string | null>(null);
  const chosen = useRef<string | null>(null);

  useEffect(() => {
    const ids = idList ? idList.split(" ") : [];
    let frame = 0;
    const update = () => {
      frame = 0;
      const nav = navRef.current;
      // Only the sticky nav on wide screens marks where you are.
      if (!nav || getComputedStyle(nav).position !== "sticky") {
        setCurrent(null);
        return;
      }
      // Just under where the nav sticks, so a section counts once it reaches the top.
      const line = (parseFloat(getComputedStyle(nav).top) || 0) + 96;
      const tops = ids.map((id) => document.getElementById(id)?.getBoundingClientRect().top ?? Infinity);
      // A section just jumped to keeps the mark while its top is still in view.
      const picked = chosen.current ? ids.indexOf(chosen.current) : -1;
      if (picked !== -1 && tops[picked] > -1 && tops[picked] < innerHeight * 0.6) {
        setCurrent(chosen.current);
        return;
      }
      chosen.current = null;
      const scroller = document.scrollingElement;
      const atEnd = !!scroller && Math.ceil(scroller.scrollTop + innerHeight) >= scroller.scrollHeight - 2;
      let index = 0;
      tops.forEach((top, i) => {
        if (top <= line || (atEnd && top < innerHeight)) index = i;
      });
      setCurrent(ids[index] ?? null);
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };
    update();
    // Captured, so a scrolling pane anywhere above the screen counts too.
    document.addEventListener("scroll", schedule, { capture: true, passive: true });
    window.addEventListener("resize", schedule);
    return () => {
      cancelAnimationFrame(frame);
      document.removeEventListener("scroll", schedule, { capture: true });
      window.removeEventListener("resize", schedule);
    };
  }, [navRef, idList]);

  const choose = useCallback((id: string) => {
    chosen.current = id;
  }, []);

  return { current, choose };
}

/* ---------- Screen ---------- */

/** A whole settings screen for an agent: model, connections, permissions, budget and memory. */
export function AgentSettings({
  agent,
  settings,
  onChange,
  models,
  connections,
  allowed,
  onRevoke,
  onRestore,
  effectNotes,
  spending,
  maxDailyLimit = 500,
  currency = "USD",
  locale = "en-US",
  memories,
  onClearMemory,
  sections = ALL_SECTIONS,
  title,
  description,
  headingLevel = 1,
  idPrefix = "agent-settings",
  className,
}: AgentSettingsProps) {
  const { text: announcement, announce } = useAnnouncer();
  const { saves, save } = useSaves(announce);
  const navRef = useRef<HTMLUListElement>(null);
  const money = useMemo(() => new Intl.NumberFormat(locale, { style: "currency", currency }), [locale, currency]);
  const moneyFormat = useMemo(() => ({ style: "currency" as const, currency }), [currency]);

  const available: Record<AgentSettingsSection, boolean> = {
    model: settings.model !== undefined && !!models?.length,
    connections: connections !== undefined,
    permissions: settings.policy !== undefined || allowed !== undefined,
    usage: settings.dailyLimit !== undefined || spending !== undefined,
    memory: settings.remember !== undefined || memories !== undefined,
  };
  const shown = sections.filter((s, i) => available[s] && sections.indexOf(s) === i);
  const sectionId = (s: AgentSettingsSection) => `${idPrefix}-${s}`;
  const { current, choose } = useCurrentSection(navRef, shown.map(sectionId).join(" "));

  const level = headingLevel;
  const change = (key: string, patch: Partial<AgentSettingsValue>, said: string) => save(key, () => onChange?.(patch), said);

  const { policy, dailyLimit } = settings;
  const used = spending?.used ?? 0;
  const reached = dailyLimit !== undefined && spending !== undefined && used >= dailyLimit;

  function body(section: AgentSettingsSection) {
    switch (section) {
      case "model": {
        const list = models ?? [];
        return (
          <div className={styles.rows}>
            <Row
              label="Default model"
              description="Used for new conversations. Ones already started keep the model they began with."
              save={saves.model}
              control={() => (
                <ModelPicker
                  models={list}
                  value={settings.model!}
                  align="end"
                  className={styles.model}
                  label="Model for new conversations"
                  onValueChange={(id) => {
                    const name = list.find((m) => m.id === id)?.name ?? id;
                    change("model", { model: id }, `Saved. New conversations use ${name}.`);
                  }}
                />
              )}
            />
          </div>
        );
      }

      case "connections":
        return <Connections agent={agent} {...connections!} className={styles.connections} />;

      case "permissions":
        return (
          <div className={styles.subsections}>
            {allowed !== undefined && (
              <div className={styles.subsection}>
                <div className={styles.subHead}>
                  <Heading level={level + 2} className={styles.subTitle}>
                    Always allowed
                  </Heading>
                  <p className={styles.intro}>Tools you chose Always allow for. Revoke one and {agent} asks again next time.</p>
                </div>
                <AllowedTools agent={agent} allowed={allowed} onRevoke={onRevoke} onRestore={onRestore} announce={announce} />
              </div>
            )}
            {policy && (
              <div className={styles.subsection}>
                <div className={styles.subHead}>
                  <Heading level={level + 2} className={styles.subTitle}>
                    Everything else
                  </Heading>
                  <p className={styles.intro}>For every other tool, by what it does.</p>
                </div>
                <div className={styles.rows}>
                  {EFFECT_ORDER.map((effect) => {
                    const { label, weighty, note } = EFFECTS[effect];
                    const value = effect === "read" || effect === "change" ? policy[effect] : "ask";
                    return (
                      <Row
                        key={effect}
                        label={label}
                        description={effectNotes?.[effect] ?? note(agent)}
                        save={saves[`policy-${effect}`]}
                        control={(ids) => (
                          <SegmentedControl
                            aria-labelledby={ids.label}
                            aria-describedby={ids.description}
                            value={value}
                            widths="content"
                            className={styles.policy}
                            onValueChange={(next) => {
                              if (effect !== "read" && effect !== "change") return;
                              const to = next as AskPolicy;
                              change(
                                `policy-${effect}`,
                                { policy: { ...policy, [effect]: to } },
                                `Saved. ${label}: ${to === "allow" ? "allowed without asking" : "ask every time"}.`,
                              );
                            }}
                          >
                            <Segment value="ask">Ask every time</Segment>
                            <Segment value="allow" disabled={weighty}>
                              Allow
                            </Segment>
                          </SegmentedControl>
                        )}
                      />
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        );

      case "usage": {
        const limitText = dailyLimit !== undefined ? money.format(dailyLimit) : "";
        const left = dailyLimit !== undefined ? money.format(Math.max(dailyLimit - used, 0)) : "";
        return (
          <div className={styles.rows}>
            {spending && dailyLimit !== undefined && (
              <div className={styles.block}>
                <UsageBreakdown
                  kind="money"
                  label="Spent today"
                  period="today"
                  agent={agent}
                  used={used}
                  limit={dailyLimit}
                  segments={spending.segments}
                  currency={currency}
                  locale={locale}
                  messages={
                    reached
                      ? { danger: `Limit reached. ${agent} stops and asks before spending more today.` }
                      : {
                          warning: `${left} left. ${agent} stops and asks at ${limitText}.`,
                          danger: `Only ${left} left. ${agent} stops and asks at ${limitText}.`,
                        }
                  }
                />
              </div>
            )}
            {dailyLimit !== undefined && (
              <Row
                label="Daily limit"
                align="field"
                description={
                  reached
                    ? `${agent} reached ${limitText} today and is waiting for you. Raise the limit to let it carry on.`
                    : `${agent} stops and asks when it reaches ${limitText} today.`
                }
                save={saves.limit}
                control={() => (
                  <NumberInput
                    label="Daily limit"
                    hideLabel
                    className={styles.limit}
                    value={dailyLimit}
                    min={1}
                    max={maxDailyLimit}
                    hint={`Up to ${money.format(maxDailyLimit)}`}
                    format={moneyFormat}
                    locale={locale}
                    steppers={false}
                    onValueChange={(next) => change("limit", { dailyLimit: next }, `Saved. Daily limit ${money.format(next)}.`)}
                  />
                )}
              />
            )}
          </div>
        );
      }

      case "memory":
        return (
          <Memory
            agent={agent}
            remember={settings.remember}
            memories={memories}
            onClear={onClearMemory}
            rememberSave={saves.remember}
            save={(on) =>
              change(
                "remember",
                { remember: on },
                on ? `Saved. ${agent} remembers between conversations.` : `Saved. ${agent} won’t remember anything new.`,
              )
            }
            announce={announce}
          />
        );
    }
  }

  const INTRO: Partial<Record<AgentSettingsSection, string>> = {
    connections: `MCP servers give ${agent} its tools. Turning one off keeps its sign-in.`,
    permissions: `What ${agent} may do without asking you first.`,
    usage: `What ${agent} has spent today, and where it stops.`,
    memory: `What ${agent} carries from one conversation to the next.`,
  };

  return (
    <div className={className ? `${styles.root} ${className}` : styles.root}>
      <header className={styles.header}>
        <Heading level={level} className={styles.title}>
          {title ?? `${agent} settings`}
        </Heading>
        {description && <p className={styles.lede}>{description}</p>}
      </header>

      <div className={styles.layout}>
        {shown.length > 1 && (
          <nav className={styles.nav} aria-label="Settings sections">
            <ul ref={navRef} className={styles.navList}>
              {shown.map((s) => (
                <li key={s}>
                  <a
                    href={`#${sectionId(s)}`}
                    className={styles.navLink}
                    aria-current={current === sectionId(s) ? "true" : undefined}
                    onClick={() => choose(sectionId(s))}
                  >
                    {SECTION_TITLE[s]}
                  </a>
                </li>
              ))}
            </ul>
          </nav>
        )}

        <div className={styles.content}>
          {shown.map((s) => (
            <Section key={s} id={sectionId(s)} level={level + 1} title={SECTION_TITLE[s]} intro={INTRO[s]}>
              {body(s)}
            </Section>
          ))}
        </div>
      </div>

      <span role="status" className={styles.srOnly}>
        {announcement}
      </span>
    </div>
  );
}
